  public function verificaPrilegio($currentForm , $localizacion = 0)
  {
	$url_base = sfConfig::get('base_simad');
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	switch($localizacion){
		case 1:
			if(!$this->getUser()->checkPerm('archivo_gestion/'.$currentForm, $usuariologuiado)){
				$this->redirect($url_base.'/no_autorizado.html');
			}
			break;
		case 2:
			if(!$this->getUser()->checkPerm('archivo_central/'.$currentForm, $usuariologuiado)){
				$this->redirect($url_base.'/no_autorizado.html');
			}
