			if(!$this->getUser()->checkPerm('archivo_historico/'.$currentForm, $usuariologuiado)){
				$this->redirect($url_base.'/no_autorizado.html');
			}
			break;
		default:
			$this->redirect($url_base.'/no_autorizado.html');
	}
  }
  
