  public function getPermSubseriesPorUsuario($usuario_id,$dependencia_id) {
  	// PARA CARPTURAR DEPENDENCIAS DE SUBSERIES POR USUARIO EN ARCHIVO DE GESTION
  	$s = new Criteria();
  	$s->setDistinct();
  	$s->addJoin(SubseriePorUsuarioPeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID);
  	$s->addJoin(SubseriePeer::SERIE_ID, SeriePeer::SERIE_ID);
  	$s->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
  	$s->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_id);
    $s->add(SubseriePorUsuarioPeer::VISUALIZACION,true);
  	/*******************************************************************************/
  	$s->clearSelectColumns();
  	/*******************************************************************************/
  	$s->addSelectColumn(DependenciaPeer::DEPENDENCIA_ID);
  	$s->addSelectColumn(SubseriePorUsuarioPeer::SUBSERIE_ID);
  	/*******************************************************************************/
  	$resultset = SubseriePorUsuarioPeer::doSelectStmt($s);
  	$subseries_disponibles = array();
  	while($object = $resultset->fetch())
  	{
  		if($object[0] != $dependencia_id)
  		{
  			$subseries_disponibles[] = $object[1];
  		}
  	}
  	/*******************************************************************************/  	
  	return  $subseries_disponibles;
  	/*******************************************************************************/
  }
  
  public function getPermSubseriePorUserCount($usuario_id,$subserie_id)
  {
  	$usuario_conectado = UsuarioPeer::retrieveByPK($usuario_id);
  	$dependencia_conectado = $usuario_conectado->getDependenciaId();
  	/*******************************************************************************/  	
  	$s = new Criteria();
  	$s->setDistinct();
  	$s->addJoin(SubseriePorUsuarioPeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID);
  	$s->addJoin(SubseriePeer::SERIE_ID, SeriePeer::SERIE_ID);
  	$s->addJoin(SeriePeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID);
  	$s->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_id);
  	//*******************************************************************************
  	$cton0 = $s->getNewCriterion(SubseriePorUsuarioPeer::SUBSERIE_ID, $subserie_id);
  	$cton1 = $s->getNewCriterion(DependenciaPeer::DEPENDENCIA_ID,$dependencia_conectado);  	
  	$cton0->addOr($cton1);
  	$s->add($cton0);
  	//*******************************************************************************
  	$count_subseries = SubseriePorUsuarioPeer::doCount($s);
  	//*******************************************************************************  	
  	return  $count_subseries;
  	/*******************************************************************************/
  }
  
