  public function getFechaVenceExp(UnidadDocumental $expediente, $fecha_tvd)
  {
    $subserie = $expediente->getSubserie();
    if($expediente->getLocalizacionunidaddocumentalId() == 1){
    	$campo_vencimiento = $expediente->getFechaApertura();    	
    	if($expediente->getFechaApertura() <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnGestion();
		}
    }elseif($expediente->getLocalizacionunidaddocumentalId() == 2){
    	$campo_vencimiento = $expediente->getFechaCierre();
		if($campo_vencimiento <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnCentral();
		}
    }elseif($expediente->getLocalizacionunidaddocumentalId() == 3){
    	$campo_vencimiento = $expediente->getFechaCierre();
		if($campo_vencimiento <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnHistorico();
    	}
	}
    
    try{
    	$date = new DateTime($campo_vencimiento);
        $date->modify("+$tiempo_retencion year");
    	$fnew = $date->format('Y-m-d');
        $expediente->setFechavencimiento($fnew);
        $expediente->save();
    }catch (Exception $ex){ echo $ex; }
  }
  
  public function getTrdFechaVenceExp($subserie_valoracion, $fecha_cierre_exp, $fecha_tvd, $valoracion_tvd)
  {
    /*echo "<pre>";
    echo $subserie_valoracion;
    echo "<pre>";
    echo $fecha_cierre_exp;
    echo "<pre>";
    echo $fecha_tvd;
    echo "<pre>";
    echo $valoracion_tvd;
    echo "<pre>";*/
    if(date("Y-m-d",strtotime($fecha_cierre_exp)) <= date("Y-m-d",strtotime($fecha_tvd))){
		$tiempo_retencion = $valoracion_tvd;
	}else{
	    $tiempo_retencion = $subserie_valoracion;
	}    
    //**********************************************************************************
    try{
    	$date = new DateTime($fecha_cierre_exp);
        $date->modify("+$tiempo_retencion year");
    	$fnew = $date->format('Y-m-d');
        return $fnew;
    }catch (Exception $ex){ return null; echo $ex; }
  }
  
  public function executeReplaceDataTrd()
