        $this->list_localizacion = LocalizacionUnidadDocumentalPeer::doSelect($c1);
        $this->is_display = false;
        $this->display_localizacion = true;
    }else{
        $this->is_display = false;
    }
    //************************************************************************************************************
  }
  
