           $c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
           $c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
           /*$c->addJoin(SubseriePeer::SUBSERIE_ID, UnidadDocumentalPeer::SUBSERIE_ID);
           $cton0 = $c->getNewCriterion(DependenciaPeer::DEPENDENCIA_ID,$dependencia_conectado);
 	       $cton1 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID,$usuariologuiado);
       	   $cton0->addOr($cton1);
       	   $c->add($cton0);*/
        }else{
           $c->addJoin(SubseriePeer::SUBSERIE_ID, UnidadDocumentalPeer::SUBSERIE_ID);
        }
        $c->add(SeriePeer::DEPENDENCIA_ID,$this->dependencia_id);
        $c->addAscendingOrderByColumn(SeriePeer::DESCRIPCION);
        $this->series = SeriePeer::doSelect($c);
