        $c->addAscendingOrderByColumn(SubseriePeer::DESCRIPCION);
        $this->subseries = SubseriePeer::doSelectJoinAll($c);
        $this->loadareas = true;
        $this->loadseries = true;
        $this->filterselect = 'dependencia';        
