  public function executeCargarCombos()
  {
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $objusuario = UsuarioPeer::retrieveByPK($usuario_conectado);
    $entidad_id = $objusuario->getRegional()->getEntidadId();
    $dependencia_id = $objusuario->getDependenciaId();
    $id_seleccion = trim($this->getRequestParameter('id_seleccionado'));
    $combo = trim($this->getRequestParameter('combo_seleccionado'));
    $id_permiso = trim($this->getRequestParameter('id_permiso'));
	//******************************************************************************************************
    $this->form_tag = trim($this->getRequestParameter('form_tag'));
    $this->addcomp = trim($this->getRequestParameter('addcomp')) != "" ? trim($this->getRequestParameter('addcomp')) : 0;
    $this->disable_combo = "";
	//******************************************************************************************************
    $perm_all_subseries = $this->tienePrilegio("VER_TODAS_LAS_SUBSERIES");
    $view_alldep = $perm_all_dep = $this->tienePrilegio("VER_TODAS_LAS_DEPENDENCIAS");
    $perm_all_entidad = $this->tienePrilegio("LISTAR_EXPEDIENTES_TODAS_ENTIDADES");
    $perm_any_trd = $this->tienePrilegio("ARCHIVO_CREAR_EXPEDIENTE_TVD");
	//******************************************************************************************************
    if(!$id_seleccion){
    	$this->disable_combo = 'disabled="disabled"';
    }
	//******************************************************************************************************
	if(!empty($id_seleccion)){
		switch($combo){
			case "macroproceso":{//cargar combo de procesos            
				$c = new Criteria();
				$c->add(ProcesosPeer::MACROPROCESO_ID,$id_seleccion);
				$c->addAscendingOrderByColumn(ProcesosPeer::DESCRIPCION);
				$this->procesos = ProcesosPeer::doSelect($c);               
			break;
			}
			case "proceso":{//cargar combo de oficinas productoras
				$c = new Criteria();
				$c->add(OficinaProductoraPeer::PROCESOS_ID,$id_seleccion);
				$c->addAscendingOrderByColumn(OficinaProductoraPeer::DESCRIPCION);
				$this->oficina_productora = OficinaProductoraPeer::doSelect($c);                           
			break;
			}
			case "dependencias_anterior":{//cargar combo dependencia anterior            
				$c = new Criteria();
				if($id_permiso == 2){
					$c->addJoin(DependenciaPeer::DEPENDENCIA_ID, SeriePeer::DEPENDENCIA_ID);                
					$c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
					$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
					$c->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
					if(!$this->tienePrilegio("VER_TODAS_LAS_DEPENDENCIAS")){
						$c->add(DependenciaPeer::ENTIDAD_ID, $entidad_id);
					}
				}
				$c->add(DependenciaPeer::OFICINAPRODUCTORA_ID,$id_seleccion);
				$c->add(DependenciaPeer::ES_ACTUAL,false);
				$c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
				$this->dependencias_anterior = DependenciaPeer::doSelect($c);               
			break;
			}
			case "unidad_administrativa":{//cargar combo de dependencias nuevas            
				$c = new Criteria();
				$c->setDistinct();
				if(($id_permiso == 2) && !$view_alldep){
					$c->addJoin(DependenciaPeer::DEPENDENCIA_ID, SeriePeer::DEPENDENCIA_ID);                
					$c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
					$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
					$c->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);               
					if(!$view_alldep){
						$c->add(DependenciaPeer::ENTIDAD_ID, $entidad_id);
					}
				}
				$c->add(DependenciaPeer::OFICINAPRODUCTORA_ID,$id_seleccion);
				$c->add(DependenciaPeer::ES_ACTUAL,true);
				$c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
				$this->dependencias = DependenciaPeer::doSelect($c);                           
			break;
			}
			case "dependencias":{//cargar combo de series            
				$c = new Criteria();
				$c->setDistinct();
				//********************************************************************************************
				if(($id_permiso == 2) && (!$perm_all_dep) && ($this->form_tag == 1) && ($id_seleccion != $dependencia_id)){//CONSULTAR
					$currentFormListAllEntidad = "LISTAR_DEPENDENCIAS_ENTIDAD";
					if($this->getUser()->checkPerm($currentFormListAllEntidad, $usuario_conectado)){
						$c->add(DependenciaPeer::ENTIDAD_ID, $entidad_id);               		
					}else{
						$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
						$c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
						$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
						$c->add(SubseriePorUsuarioPeer::VISUALIZACION,1);
						$c2 = $c->getNewCriterion(SeriePeer::DEPENDENCIA_ID, $dependencia_id);
						$c3 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
						$c3->addOr($c2);
						$c->add($c3);
					}
				}elseif(($id_permiso == 1) && ($this->form_tag == 2) && ($id_seleccion != $dependencia_id) && !$perm_all_subseries){//CREACION
					if($perm_all_subseries){
						$c->add(DependenciaPeer::ENTIDAD_ID, $entidad_id);               		
					}else{
					$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
					$c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
					$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
					$c->add(SubseriePorUsuarioPeer::CREACION,1);
					$c2 = $c->getNewCriterion(SeriePeer::DEPENDENCIA_ID, $dependencia_id);
					$c3 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
					$c3->addOr($c2);
					$c->add($c3);
				}
				}
				//********************************************************************************************
				if($this->form_tag != 1){
					$c->add(SeriePeer::ES_VISIBLE,1);
				}
				//********************************************************************************************
				$c->add(SeriePeer::DEPENDENCIA_ID,$id_seleccion);
				$c->addAscendingOrderByColumn(SeriePeer::DESCRIPCION);
				$this->series = SeriePeer::doSelect($c);               
				break;
			}        
			case "series":{//cargar combo de subseries
				$serie = SeriePeer::retrieveByPK($id_seleccion);
				$dependencia_select = $serie->getDependenciaId();
				//*********************************************************************************************
				$c = new Criteria();
				$c->setDistinct();
				//*********************************************************************************************
				if(($id_permiso == 2) && (!$perm_all_dep)  && ($this->form_tag == 1) && ($dependencia_id != $dependencia_id)){//CONSULTAR
					$c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
					$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
					$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
					$c->add(SubseriePorUsuarioPeer::VISUALIZACION,1);
					$c2 = $c->getNewCriterion(SeriePeer::DEPENDENCIA_ID, $dependencia_id);
					$c3 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
					$c3->addOr($c2);
					$c->add($c3);
				}elseif(($id_permiso == 1) && ($this->form_tag == 2) && ($dependencia_id != $dependencia_id)){//CREACION
					$c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
					$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
					$c->addJoin(SubseriePeer::SUBSERIE_ID, SubseriePorUsuarioPeer::SUBSERIE_ID);
					$c->add(SubseriePorUsuarioPeer::CREACION,1);
					$c2 = $c->getNewCriterion(SeriePeer::DEPENDENCIA_ID, $dependencia_id);
					$c3 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
					$c3->addOr($c2);
					$c->add($c3);
				}
				//********************************************************************************************
				if($this->form_tag != 1){ $c->add(SubseriePeer::ES_VISIBLE,1); }
				//*********************************************************************************************
				$c->add(SubseriePeer::SERIE_ID,$id_seleccion);
				$c->addAscendingOrderByColumn(SubseriePeer::DESCRIPCION);
				$this->subseries = SubseriePeer::doSelect($c);
				break;
			}
		}
	}
	//**********************************************************************************************************
    $this->id_permiso = $id_permiso;
  }
  
    
  public function executeCargar(){
  		$c = new Criteria();
		$c->setDistinct();
  		$combo =$this->getRequestParameter('combo_box'); 
  		// SI ES ARCHIVO DE GESTION
	  	$permiso = $this->getRequestParameter('permiso');
	  	if($permiso == 2){
		  	// PARA CARPTURAR DATOS DE SUBSERIES POR USUARIO EN GESTION DOCUMENTAL
		  	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		  	$s = new Criteria();
			$s->setDistinct();
		  	$s->add(SubseriePorUsuarioPeer::USUARIO_ID, $usuario_conectado);
		  	$lista_subseries = SubseriePorUsuarioPeer::doSelect($s);
		  	$subseries_disponibles = array();
		  	foreach($lista_subseries as $subserie){
				$subseries_disponibles[] = $subserie->getSubserieId();
			}
		  	
		  	// CONSULTA DE SERIES
		  	if($combo == 'series'){
			  	$c->addJoin(SeriePeer::SERIE_ID, SubseriePeer::SERIE_ID);
			}
			
			$c->add(SubseriePeer::SUBSERIE_ID, $subseries_disponibles, Criteria::IN);	
			
		}
  	
  		 	
  		if($combo == 'series'){
  			$c->add(SeriePeer::DEPENDENCIA_ID, $this->getRequestParameter('id_seleccion'));
  			$c->addAscendingOrderByColumn(SeriePeer::DESCRIPCION);
  			$this->consulta = SeriePeer::doSelect($c);
  		}else{
  			$c->add(SubseriePeer::SERIE_ID, $this->getRequestParameter('id_seleccion'));
  			$c->addAscendingOrderByColumn(SubseriePeer::DESCRIPCION);
  			$this->consulta = SubseriePeer::doSelect($c);			
		}
		
	}

