  public function executeShow()
  {  	
  	$origen = $this->getRequestParameter('origen');
  	if($origen == ""){ $origen = 1; }
	//**************************************************************************************************************/
	$this->boton = $origen;
	$localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');	
	$currentForm="show";
  	$this->verificaPrilegioCerrar($currentForm,$localizacion);	
    $unidad_documental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));    
    //**************************************************************************************************************/
	$this->expediente_origen = "";
	if(!empty($unidad_documental->getParentunidaddocId())){
		$unidaddoc_parent = UnidadDocumentalPeer::retrieveByPk($unidad_documental->getParentunidaddocId()); 
		$this->expediente_origen = sprintf("%s - %s",$unidaddoc_parent->getCodigoBarras(),$unidaddoc_parent->getTitulo());
	}
	//**************************************************************************************************************/
	$cu = new Criteria();
	$cu->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
	$cu->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));
	$this->contador_contenido  = ContenidoUnidadDocumentalPeer::doCount($cu);
    //**************************************************************************************************************/
	$usuariologueado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$s = new Criteria();
	$s->add(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));
	$s->add(SolicitudPrestamoPeer::SOLICITUDPRESTAMOESTADO_ID,1);
	$s->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,NULL);
	$s->add(SolicitudPrestamoPeer::USUARIO_ID,$usuariologueado);
	$this->contador  = SolicitudPrestamoPeer::doCount($s);
	//**************************************************************************************************************/
    /*Verificar que el documento no este en gestion y realizar la consulta en prestamos**/
    if($unidad_documental->getLocalizacionunidaddocumentalId() != 1){
		$c = new Criteria();
		$c->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);	
		$c->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);	
		$c->add(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));
		$c->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,NULL);		
		$this->solicitud_prestamo  = DetallePrestamoPeer::doCount($c);							
	}
	//**************************************************************************************************************/
	$a = new Criteria();			
	$a->add(ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));		
	$this->total_documentos  = ContenidoUnidadDocumentalPeer::doCount($a);
	//**************************************************************************************************************/
	$p = new Criteria();			
	$p->addJoin(DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID);
	$p->add(SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID,$this->getRequestParameter('unidaddocumental_id'));
	$p->add(DetallePrestamoPeer::ESTADOPRESTAMO_ID,1);	
	$p->add(SolicitudPrestamoPeer::CONTENIDOUNIDADDOCUMENTAL_ID,NULL,Criteria::NOT_EQUAL);				
	$this->cantidad_doc_prestados  = SolicitudPrestamoPeer::doCount($p);
	//**************************************************************************************************************/
    $this->codigos_anteriores = 0;
    //**************************************************************************************************************/
	$permisoDeAccesiACarpeta = array();
