  public function executeUpdateReabrirExpediente()
  {  
	$msg_error = '';
	$url_base = sfConfig::get('base_simad');
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	//****************************************************************************************************************
	if(!$this->tienePrilegio('ARCHIVO_REABRIR_EXPEDIENTE')){//PERMISOS
		$this->redirect($url_base.'/no_autorizado.html');
	}
	//****************************************************************************************************************
	$unidaddocumental_id = trim($this->getRequestParameter('unidaddocumental_id'));
	$unidad_documental = UnidadDocumentalPeer::retrieveByPK($unidaddocumental_id);
	//****************************************************************************************************************
	if($unidad_documental->getEstaCerrado() != 1){
		$this->redirect($url_base.'/no_autorizado_cerrar.html');
	}
	//****************************************************************************************************************
    try
    {
		$fecha_apertura = trim($this->getRequestParameter('fecha_apertura'));
		$fecha_cierre = null;
		$notas = trim($this->getRequestParameter('notas')) ? trim($this->getRequestParameter('notas')) : null;
		$ubicacion_expediente = trim($this->getRequestParameter('ubicacion_expediente')) ? trim($this->getRequestParameter('ubicacion_expediente')) : null;
		$folios = trim($this->getRequestParameter('folios')) ? trim($this->getRequestParameter('folios')) : 1;
		$localizacion = trim($this->getRequestParameter('localizacion'));
		$new_volumen = $unidad_documental->getVolumen() + 1; 
		//************************************************************************************************************
		if(empty($fecha_apertura) || empty($ubicacion_expediente) || empty($folios))
		{
			$this->getUser()->setFlash('error', 'Debe diligenciar todos los campos obligatorios');
			return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/reabrirFormUnidadDocumental?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$unidad_documental->getLocalizacionunidaddocumentalId());
		}
		
		$fecha_vencimiento = $unidad_documental->getFechaVencimientoNewFase($fecha_apertura);
		//************************************************************************************************************
		$new_unidad_documental = $unidad_documental->copy();
		$unidaddoc_anterior = clone $unidad_documental;
		$newestadounidaddoc_id = 5;
		$parentestadounidaddoc_id = 6;
		//************************************************************************************************************
		$new_unidad_documental->setFechaApertura($fecha_apertura);
		$new_unidad_documental->setFechaCierre($fecha_cierre);
		$new_unidad_documental->setFechaCreacion(date('Y-m-d G:i:s'));
		$new_unidad_documental->setNotas($notas);
		$new_unidad_documental->setFolios($folios);
		$new_unidad_documental->setVolumen($new_volumen);
		$new_unidad_documental->setEstaCerrado(0);
		$new_unidad_documental->setLocalizacionunidaddocumentalId(1); 
		$new_unidad_documental->setEstadounidaddocumentalId($newestadounidaddoc_id);
		$new_unidad_documental->setEstadotransferencia(null); 
		$new_unidad_documental->setActaCierre(null); 
		$new_unidad_documental->setObsCierre(null); 
		$new_unidad_documental->setEidxRelpath(null); 
		$new_unidad_documental->setEidxAbspath(null); 
		$new_unidad_documental->setMarca(null); 
		$new_unidad_documental->setUbicacionengestion($ubicacion_expediente);
		$new_unidad_documental->setUbicacionencentral(null);
		$new_unidad_documental->setUbicacionenhistorico(null);
		$new_unidad_documental->setFechavencimiento($fecha_vencimiento); 
		$new_unidad_documental->setParentunidaddocId($unidad_documental->getPrimaryKey()); 
		$new_unidad_documental->save();
		//************************************************************************************************************
		foreach($unidad_documental->getUnidaddocumentalUsuarios() as $row_usuarios)
		{
			$new_unidad_documental_usuario = new UnidaddocumentalUsuario();
			//********************************************************************************************************
			$new_unidad_documental_usuario->setUsuarioId($row_usuarios->getUsuarioId());
			if($row_usuarios->getRolusuunidaddocId() == 1)
			{
				$new_unidad_documental_usuario->setUsuarioId($usuariologuiado);
			}else{
				$new_unidad_documental_usuario->setUsuarioId($row_usuarios->getUsuarioId());
			}
			//********************************************************************************************************
			$new_unidad_documental_usuario->setRolusuunidaddocId(1);
			$new_unidad_documental_usuario->setUnidaddocumentalId($new_unidad_documental->getPrimaryKey());
			$new_unidad_documental_usuario->save(); 
		}			
		//***************tabla UNIDADDOCUMENTAL_INTERESADOS***********************************************************
		foreach($unidad_documental->getUnidaddocumentalInteresadoss() as $row_interesados)
		{
			UnidaddocumentalInteresadosPeer::addNewInteresadoByComId($new_unidad_documental->getPrimaryKey(), $row_interesados->getInteresadoId()); 
		}
		//***************tabla METADATOS_EXPEDIENTE*******************************************************************
		foreach($unidad_documental->getMetadatosExpedientes() as $row_metadatos)
		{
			$new_metadatos_expediente = new MetadatosExpediente();

			$new_metadatos_expediente->setUsuarioId($usuariologuiado);
			$new_metadatos_expediente->setMetadatoId($row_metadatos->getMetadatoId());
			$new_metadatos_expediente->setUnidaddocumentalId($new_unidad_documental->getPrimaryKey());
			$new_metadatos_expediente->setValueField($row_metadatos->getValueField());
			$new_metadatos_expediente->setFechaCreacion(date('Y-m-d G:i:s'));
			//********************************************************************************************************
			$new_metadatos_expediente->save(); 
		}
		//************************************************************************************************************
		$unidad_documental->setEstadounidaddocumentalId($parentestadounidaddoc_id);
		$unidad_documental->save();
		//************************************************************************************************************
		AuditLogPeer::guardarAuditoriaLite("UnidadDocumental", $unidaddoc_anterior, $unidad_documental, 5, $unidad_documental->getCodigoBarras(),$usuariologuiado);
		//************************************************************************************************************
		$msg = sprintf("Expediente reabierto exitosamente, Id <strong>Expediente:</strong> %s, <strong>N&uacute;mero expediente:</strong> %s, <strong>Nombre Expediente:</strong> %s",$new_unidad_documental->getPrimaryKey(),
					$new_unidad_documental->getCodigoBarras(),$new_unidad_documental->getTitulo());
		
		$this->getUser()->setFlash('notice', $msg);
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$localizacion);			
	}
	catch (PropelException $ex)
	{
		$msg_error = 'Error creando el nuevo expediente.';
	}
	catch (\Exception $ex)
	{
		$msg_error = 'Ocurrio un error inesperado en la aplicacion. Intente de nuevo.';
	}
	catch (\Throwable $ex)
	{
		$msg_error = 'Error interno del servidor.';
	}
	//****************************************************************************************************************
	$this->getUser()->setFlash('error', $msg_error);
	return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$localizacion);
  }
  
  public function executeUpdateCloseFolder()
  {
    $unidaddocumental_id = $this->getRequestParameter('unidaddocumental_id');
    $unidad_documental = UnidadDocumentalPeer::retrieveByPk($unidaddocumental_id);
	$unidad_documental_anterior = clone $unidad_documental;
	$localizacionunidaddoc_id = $unidad_documental->getLocalizacionunidaddocumentalId();
	$url_base = sfConfig::get('base_simad');
	$source_temp = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR.'tmp';
	//**************************************************************************************************************
	if($unidad_documental->getEstaCerrado()){
		$this->getUser()->setFlash('error_data', 'El expediente ya esta cerrado');
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/closeInExpediente?unidaddocumental_id='.$unidad_documental->getPrimaryKey());
	}
	//**************************************************************************************************************
	switch ($localizacionunidaddoc_id) {
		case 1:
			$modulo = "GESTION";
			break;
		case 2:
			$modulo = "CENTRAL";
			break;
		case 3:
			$modulo = "HISTORICO";
			break;
		default:
			$modulo = "NONE";
			break;
	}
	//**************************************************************************************************************
	$currentForm = "ARCHIVO_".$modulo."_CERRAR_EXPEDIENTE";
	$permAllExp = $this->tienePrilegio($currentForm);
	//**************************************************************************************************************
	if(!$permAllExp){
		$accesoCarpeta = UnidadDocumentalPeer::getPermisoACarpeta($unidad_documental->getSubserieId(),$unidad_documental->getPrimaryKey());
		if(!isset($accesoCarpeta['creador_expediente'])){
			$this->redirect($url_base.'/no_autorizado_cerrar.html');
		}else if(empty($accesoCarpeta['creador_expediente'])){
			$this->redirect($url_base.'/no_autorizado_cerrar.html');
		}
	}
	//*************************************************************************************************************
	$tdObligFaltantes = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($unidad_documental->getSubserieId(),$unidad_documental->getPrimaryKey());
	
	if($tdObligFaltantes > 0)
	{
		$nombre_permiso = "ARCHIVO_".$modulo."_CERRAR_EXPEDIENTE_ANY";
		$permiso = $this->tienePrilegio($nombre_permiso, $localizacionunidaddoc_id);
		if(!$permiso)
		{
			$this->redirect($url_base.'/no_autorizado_cerrar.html');
		}
	}
	//*************************************************************************************************************
	$observaciones_cierre = trim($this->getRequestParameter('observaciones_cierre')) ? trim($this->getRequestParameter('observaciones_cierre')) : "";
	$fecha_cierre = trim($this->getRequestParameter('fecha_cierre')) ? trim($this->getRequestParameter('fecha_cierre')) : null;
	$acta_cierre = trim($this->getRequestParameter('acta_cierre')) ? trim($this->getRequestParameter('acta_cierre')) : null;
	$newestadounidaddoc_id = 4;
	//*************************************************************************************************************
	if(empty($observaciones_cierre) || empty($fecha_cierre)){
		$this->getUser()->setFlash('error_data', 'Hay campos obligatorios que no fueron diligenciados');
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/closeInExpediente?unidaddocumental_id='.$unidad_documental->getPrimaryKey());
	}
	//*************************************************************************************************************
	$unidad_documental->setEstaCerrado(1);
	$unidad_documental->setObsCierre($observaciones_cierre);
	$unidad_documental->setFechaApertura($fecha_cierre);
	$unidad_documental->setActaCierre($acta_cierre);
	//*************************************************************************************************************
	$new_vencimiento = $unidad_documental->getFechaVencimientoCustom($fecha_cierre);
	//*************************************************************************************************************
	$unidad_documental->setFechavencimiento($new_vencimiento);
	$unidad_documental->setEstadounidaddocumentalId($newestadounidaddoc_id);
	//*************************************************************************************************************
	//GENERAR INDICE ELECTRONICO XXX
	$genFileInDisk = true;
	$filename = $unidad_documental->generateIndiceElectronico($genFileInDisk);
	$target_path = $source_temp.DIRECTORY_SEPARATOR.$filename;

	if(file_exists($target_path))
	{
		$response = $unidad_documental->singExpDocumentProcess($target_path,true);
		//*********************************************************************************************************
		$unidad_documental->save();
		//*********************************************************************************************************
		AuditLogPeer::guardarAuditoriaLite("UnidadDocumental",$unidad_documental_anterior,$unidad_documental,ModulesEnable::Archivo,$unidad_documental->getCodigoBarras());
		//*********************************************************************************************************
		if($response['httpStatus'] != 200){
			$this->getUser()->setFlash('error', 'Ocurrio un error firmando el indice electronico, el expediente se cerro sin embargo el indice electronico no se firmo');
			//return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/closeInExpediente?unidaddocumental_id='.$unidad_documental->getPrimaryKey());
		}else{
			$this->getUser()->setFlash('expediente_close', 'El expediente se cerro satisfactoriamente, por favor valide el indice electronico');
		}
	}
	else
	{
		$this->getUser()->setFlash('error_data', 'Ocurrio un error al generar el archivo del indice electronico, no puede cerrar el expediente');
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/closeInExpediente?unidaddocumental_id='.$unidad_documental->getPrimaryKey());
	}
	//*************************************************************************************************************
    $this->unidad_documental = $unidad_documental;
	//*************************************************************************************************************
	return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey()."&localizacionunidaddocumental_id=".$localizacionunidaddoc_id);
  }

  public function executeCloseInExpediente()
  {
    $unidad_documental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));
	$localizacionunidaddoc_id = $unidad_documental->getLocalizacionunidaddocumentalId();
	$url_base = sfConfig::get('base_simad');
    //**************************************************************************************************************
	switch ($localizacionunidaddoc_id) {
		case 1:
			$modulo = "GESTION";
			break;
		case 2:
			$modulo = "CENTRAL";
			break;
		case 3:
			$modulo = "HISTORICO";
			break;
		default:
			$modulo = "NONE";
			break;
	}
	//**************************************************************************************************************
	$currentForm = "ARCHIVO_".$modulo."_CERRAR_EXPEDIENTE";
	$permAllExp = $this->tienePrilegio($currentForm);
	//**************************************************************************************************************
	if(!$permAllExp){
		$accesoCarpeta = UnidadDocumentalPeer::getPermisoACarpeta($unidad_documental->getSubserieId(),$unidad_documental->getPrimaryKey());
		if(!isset($accesoCarpeta['creador_expediente'])){
			$this->redirect($url_base.'/no_autorizado_cerrar.html');
		}else if(empty($accesoCarpeta['creador_expediente'])){
			$this->redirect($url_base.'/no_autorizado_cerrar.html');
		}
	}
	//*************************************************************************************************************
	$ilist_usuarios = $unidad_documental->getListUsuariosObject();
	$usuario_responsable = isset($ilist_usuarios['usuario_responsable']) ? $ilist_usuarios['usuario_responsable'] : null;
	//var_dump($usuario_responsable);exit;
	if($usuario_responsable != null && !in_array($usuario_responsable->getEstadousuarioId(),array(4,5))){
		if(empty($usuario_responsable->getLoginFirma()) || empty($usuario_responsable->getPassFirma())){
			$this->getUser()->setFlash('error_data','El usuario responsable no tiene habilitada la firma digital, el indice electrónico no se firmara');
		}
	}elseif(in_array($usuario_responsable->getEstadousuarioId(),array(4,5))){
		$this->getUser()->setFlash('error_data','El usuario responsable del expediente esta inactivo, el indice electrónico no se puede firma');
	}else{
		$this->getUser()->setFlash('error_data','El expediente no tiene asociado un usuario responsable,el indice electrónico no se puede firma');
	}
	//**************************************************************************************************************
	$subserie_id = $unidad_documental->getSubserieId();
	$unidaddocumental_id = $unidad_documental->getPrimaryKey();
	
	$tdObligFaltantes = TipoDocumentalPeer::getCountTipoDocRequiredFaltantes($subserie_id, $unidaddocumental_id);
	$tdCierraExpFaltantes = TipoDocumentalPeer::getCountTipoDocCloseExpFaltantes($subserie_id, $unidaddocumental_id);

	if($tdObligFaltantes > 0 || $tdCierraExpFaltantes > 0)
	{
		$nombre_permiso = "ARCHIVO_".$modulo."_CERRAR_EXPEDIENTE_ANY";
		$permiso = $this->tienePrilegio($nombre_permiso, $localizacionunidaddoc_id);

		if($permiso)
		{
			$this->getUser()->setFlash('error_warning', 'El expediente no tiene los documentos obligatorios o de cierre requeridos, pero el usuario tiene permiso para cerrar el expediente de todas formas');
		}
		else
		{
			$this->getUser()->setFlash('error_warning', 'No se puede cerrar el expediente, hay documentos obligatorios para proceder para el cierre manual');
			return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacionunidaddocumental_id='.$localizacionunidaddoc_id);
		}
	}
	//**************************************************************************************************************
	$this->unidad_documental = $unidad_documental;
	$this->forward404Unless($this->unidad_documental);
  }

