  function getUrlBase() 
  {
    $http = 'http';
    if(!empty($_SERVER["HTTPS"])){
    	$http .= "s";
    }		
    $url = $http . "://".$_SERVER["HTTP_HOST"] . $_SERVER["REQUEST_URI"];
    $filename = explode("/", $url);		
    $base = "";
    for( $i = 0; $i < (count($filename) - 1); ++$i ) {
    	$base .= $filename[$i].'/';
    }
    return $base;
  }
  
