    $entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
    $regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
    $usuario_object = UsuarioPeer::retrieveByPK($usuariologuiado);
    $dependencia_conectado = $usuario_object->getDependenciaId();
    //********************************************************************************************
    /*$c = new Criteria();
    $c->setDistinct();
    $c->addJoin(DependenciaPeer::DEPENDENCIA_ID,SeriePeer::DEPENDENCIA_ID);
    $c->addJoin(SeriePeer::SERIE_ID,SubseriePeer::SERIE_ID);
    $c->addJoin(SubseriePeer::SUBSERIE_ID,UnidadDocumentalPeer::SUBSERIE_ID);
    $c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID,$localizacion);
    $c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
    $this->dependencias = DependenciaPeer::doSelect($c);*/
    //********************************************************************************************
    if($this->getRequestParameter('isad')){
    	$this->isad = new Isad();
    }
    //********************************************************************************************
    if($this->localizacion == 1){
    	$this->verificaPrilegio($currentForm,$localizacion);    	
    	$this->name_localizacion = "Gestion";
        $this->name_original = "Gestion";
        $this->permiso = 2;
    }elseif($this->localizacion == 2){		
    	$this->verificaPrilegio($currentForm,$localizacion);
    	$this->name_localizacion = "Central";
        $this->name_original = "Central";
        $this->permiso = 1;
    }elseif($this->localizacion == 3){		
    	$this->verificaPrilegio($currentForm,$localizacion);
    	$this->name_localizacion = "Historico";
        $this->name_original = "Historico";
        $this->permiso = 1;        
    }
    //*********************************************************************************************    
    $this->UserUniDoc = UsuarioPeer::getAllUser();
    //********************************************************************************************/
    $this->udr_creador = 0;
    $this->creador = 0;
    $this->udr_responsable = 0;
    $this->responsable = 0;
    $this->udr_inventariador = 0;
    $this->inventariador = 0;
    $this->unidad_documental = new UnidadDocumental();
	/*********************OBTENER EL PARAMETRO PARA EL MANEJO DE TRD*****************************/
    $param_trd = ParametroPeer::retrieveByPK(61)->getValornumerico();
    $this->tipo_manejo_trd = $param_trd;//parametro manejo de TRD 1=por dependencia, 2=por procesos
    $this->form_tag = 1;//si es consulta=1 o creacion=2
	//********************************************************************************************/
	//$this->getUser()->addCredential('ucomponet_type');
    $this->getUser()->setAttribute('form_option', md5('frmsearch'.$this->form_tag));
    //********************************************************************************************/
    $c = new Criteria();
    $c->setDistinct();
    $c->addJoin(DependenciaPeer::DEPENDENCIA_ID,SeriePeer::DEPENDENCIA_ID);
    $c->addJoin(SeriePeer::SERIE_ID,SubseriePeer::SERIE_ID);
    $c->addJoin(SubseriePeer::SUBSERIE_ID,UnidadDocumentalPeer::SUBSERIE_ID);
    if(!$this->tienePrilegio("VER_TODAS_LAS_SUBSERIES") && $this->localizacion == 1){
    	$c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePorUsuarioPeer::SUBSERIE_ID);
    	$cton0 = $c->getNewCriterion(DependenciaPeer::DEPENDENCIA_ID,$dependencia_conectado);
    	$cton1 = $c->getNewCriterion(SubseriePorUsuarioPeer::USUARIO_ID,$usuariologuiado);
    	$cton0->addOr($cton1);
    	$c->add($cton0);
    }    
    $c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID,$localizacion);
    // CONSULTA POR ENTIDAD
    $currentFormListAllEntidad = "LISTAR_EXPEDIENTES_TODAS_ENTIDADES";
    $this->entidades_list = new Entidad();    
    if(!$this->getUser()->checkPerm($currentFormListAllEntidad, $usuariologuiado)){
    	$c->add(DependenciaPeer::ENTIDAD_ID, $entidad_conectado);
    	$this->entidades_list = null;
    }    
    /********************************************************************************************/
    $c->addAscendingOrderByColumn(DependenciaPeer::NOMBRE);
    //$this->dependencias = DependenciaPeer::doSelectJoinAll($c);
	$this->dependencias = DependenciaPeer::getDependenciaPorArchivo($this->permiso,$this->form_tag,$param_trd);
    /********************************************************************************************/
    // CONSULTA POR REGIONAL
    $this->regionales = new Regional();
    //$permiso = $this->getRequestParameter('permiso');//valida tipo de archivo 1=central 2=gestion
    $this->localizacion_object = LocalizacionUnidadDocumentalPeer::retrieveByPK($this->localizacion);
    /********************************************************************************************/    
    $this->mostrarUsuario=0;
    if($this->getRequestParameter('mostrarUsuario')==1){ $this->mostrarUsuario=1; }
    $this->subserie    = new Subserie();
  }
  
