  public function executeStickers()
  {
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $base_path = sfConfig::get('base_simad');
    //************************************************************************************************************
  	$this->setLayout(false);
	//************************************************************************************************************
    $marca = $this->getRequestParameter('marcado');    
    $localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
    $ubicacion = $this->getRequestParameter('ubicacion');    
    //************************************************************************************************************
    $id_responsable = $this->getRequestParameter('id_responsable');
  	$c = new Criteria();
    $c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID, $localizacion);
    if($ubicacion != ""){
        if($localizacion == 1 ){
            $ubicacion = $this->getRequestParameter('ubicacionengestion');            
    		$c->add(UnidadDocumentalPeer::UBICACIONENGESTION, $ubicacion);
        }elseif($localizacion == 2){
            $ubicacion = $this->getRequestParameter('ubicacionencentral');            
    		$c->add(UnidadDocumentalPeer::UBICACIONENCENTRAL, $ubicacion);
    	}elseif($localizacion == 3){
    	    $ubicacion = $this->getRequestParameter('ubicacionenhistorico');            
    		$c->add(UnidadDocumentalPeer::UBICACIONENHISTORICO, $ubicacion);
    	}
    }
    //************************************************************************************************************
    if($marca != ""){
        $c->add(UnidadDocumentalPeer::MARCA, $usuariologuiado);
    }
    //************************************************************************************************************
    if($id_responsable != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		$c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID, $id_responsable);
		$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID, 3);					
	}
    //************************************************************************************************************
	$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
	if(!$this->tienePrilegio("VER_TODAS_LAS_SUBSERIES")){
	  $c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID,$usuariologuiado);
    }
	$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID,1);
	$results = UnidadDocumentalPeer::doSelect($c);
	//************************MANEJO PARA CREACION DIRECTORIO Y ARCHIVO A CONVERTIR*******************************
    //directorio temporal para guardar los archivos a convertir a pdf
    $dir_tmp = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR."com_html".DIRECTORY_SEPARATOR."archivo".DIRECTORY_SEPARATOR;
    if (!is_dir($dir_tmp)) {//verificar si el directorio existe de lo contrario se crea
      simad_util::createPath($dir_tmp,0766);//crea el directorio destiono
    }
    //nombre del archivo temporal que contiene los datos a convertir
    $aleatorio = rand(1, 10000000);  
    $hash_is = md5(uniqid().date('YmdGis').$aleatorio);    
    $nomb_file_html = simad_util::uniquename($dir_tmp,$hash_is);        
    //************************************************************************************************************
    if(file_exists($dir_tmp.$nomb_file_html)){//verificar si ya esta generado el archivo a convertir
        unlink($dir_tmp.$nomb_file_html);//se elimina para actualizar el contenido del documento
    }
    $pt = fopen($dir_tmp.$nomb_file_html, 'w');//se crea el archivo a convertir
    //************************************************************************************************************
	$dir_templates = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR."templates".DIRECTORY_SEPARATOR;
	$file_css = "rotulofolder-styles.txt";
    $contents_css = file_get_contents($dir_templates.$file_css);
	//************************************************************************************************************
	fputs($pt,'<html><body style="font: normal 5pt Verdana, Arial, sans-serif;">');
	fputs($pt,'<head><style type="text/css">'.$contents_css.'</style></head>');
	//************************************************************************************************************
    // RECORRRER LAS UNIDADES DOCUMENTALES PARA CAPTURAR EL RESPONSABLE
	foreach($results as $unidad_documental)
	{
	    $unidad_documental->createFileRotuloCarpeta($pt);
	}
	//************************************************************************************************************
	fputs($pt,"</body></html>");
    //Cierra el archivo y envia para generar el pdf    
    fclose($pt);
    //************************************************************************************************************
    $this->redirect($base_path.'/generatepdf.php?rotulocarpeta_id='.$nomb_file_html);
  }

  public function executeRotuloCaja()
  {

	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $base_path = sfConfig::get('base_simad');
    //************************MANEJO PARA CREACION DIRECTORIO Y ARCHIVO A CONVERTIR*******************************
    //directorio temporal para guardar los archivos a convertir a pdf
    $dir_tmp = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR."com_html".DIRECTORY_SEPARATOR."archivo".DIRECTORY_SEPARATOR;
    if (!is_dir($dir_tmp)) 
	{//verificar si el directorio existe de lo contrario se crea
      simad_util::createPath($dir_tmp,0766);//crea el directorio destiono
    }
    //nombre del archivo temporal que contiene los datos a convertir
    $aleatorio = rand(1, 10000000);  
    $hash_is = md5(time().$aleatorio);    
    $nomb_file_html = simad_util::uniquename($dir_tmp,$hash_is);        
    //*******************************************************************************************************
    if(file_exists($dir_tmp.$nomb_file_html))
	{//verificar si ya esta generado el archivo a convertir
        unlink($dir_tmp.$nomb_file_html);//se elimina para actualizar el contenido del documento
    }
    $pt = fopen($dir_tmp.$nomb_file_html, 'w');//se crea el archivo a convertir
    //*******************************************************************************************************
	$dir_templates = sfConfig::get('sf_web_dir').DIRECTORY_SEPARATOR."templates".DIRECTORY_SEPARATOR;
	$file_css = "rotulocaja-styles.txt";
    $contents_css = file_get_contents($dir_templates.$file_css);
	//*******************************************************************************************************
	fputs($pt,'<html><body style="font: normal 5pt Verdana, Arial, sans-serif;">');
	fputs($pt,'<head><style type="text/css">'.$contents_css.'</style></head>');
	//******************************************OBTENEMOS LOS DATOS GENERALES DE LA CAJA*********************
	$c = new Criteria();
	$c->clearSelectColumns();
	$c->addSelectColumn(UnidadDocumentalPeer::NUMERO_CAJA);
	$c->addAsColumn('FECH_INICIO', 'MIN('.UnidadDocumentalPeer::FECHA_APERTURA.')');
	$c->addAsColumn('FECH_FIN', 'MAX('.UnidadDocumentalPeer::FECHA_CIERRE.')');
	$c->addAsColumn('ANIO_INICIAL', 'YEAR(MIN(' . UnidadDocumentalPeer::FECHA_APERTURA . '))');
	$c->addAsColumn('ANIO_FINAL', 'YEAR(MIN(' . UnidadDocumentalPeer::FECHA_CIERRE . '))');
	$c->addAsColumn('TOTAL', 'COUNT(1)');
	$c->add(UnidadDocumentalPeer::NUMERO_CAJA, null, Criteria::ISNOTNULL);
	$c->add(UnidadDocumentalPeer::NUMERO_CAJA, '', Criteria::NOT_EQUAL);
	$c->add(UnidadDocumentalPeer::MARCA, $usuariologuiado);
	$c->addGroupByColumn(UnidadDocumentalPeer::NUMERO_CAJA);
	//******************************************BUCLE DENTRO DE BUCLE****************************************
	$unidad_documental_list = UnidadDocumentalPeer::doSelectStmt($c)->fetchAll();
	//******************************************BUCLE DENTRO DE BUCLE****************************************
	foreach($unidad_documental_list as $object)
	{
		UnidadDocumentalPeer::createFileRotuloCaja($pt, $object);
	}
	//*******************************************************************************************************
	fputs($pt,"</body></html>");
    //Cierra el archivo y envia para generar el pdf    
    fclose($pt);
    //*******************************************************************************************************
    $this->redirect($base_path.'/generatepdf.php?rotulocaja_id='.$nomb_file_html);
	$this->setLayout(false);
  }
  
