		$dir_jar = sfConfig::get('sf_lib_dir') . DIRECTORY_SEPARATOR . 'pd4ml' . DIRECTORY_SEPARATOR . 'pd4ml.jar';
		$dir_font = sfConfig::get('sf_lib_dir') . DIRECTORY_SEPARATOR . 'pd4ml' . DIRECTORY_SEPARATOR . 'fonts' . DIRECTORY_SEPARATOR;
		$fullpath_source = sfConfig::get('sf_web_dir') . DIRECTORY_SEPARATOR . "tmp" . DIRECTORY_SEPARATOR . $filename;
		//******************************************************************************************************
		$format_page = "A4";
		$size_point_page = "840";
		$font_use = "-ttf $dir_font";
		$margins = '-insets ' . $margins_list['top'] . ',' . $margins_list['left'] . ',' . $margins_list['buttom'] . ',' . $margins_list['rigth'] . ',mm';
		$outfile = "-out \"$fullpath_source\"";
		$orientation = '-orientation LANDSCAPE';
        $watermark = "";
        $adjustwidth = "";
		//******************************************************************************************************
		if (strpos(php_uname(), 'Windows') !== FALSE) 
		{
			// server platform: Windows
			$dir_jar = preg_replace('/\//', "\\", $dir_jar);
			$cmdline = "$java -Xmx512m -cp $dir_jar Pd4Cmd \"$url\" $size_point_page $format_page $orientation $margins $adjustwidth $watermark $font_use $outfile";
		} 
		else 
		{
			$font_use = "";
			$cmdline = "$java -XX:MaxHeapSize=8m -XX:CompressedClassSpaceSize=64m -XX:+UseSerialGC -Djava.awt.headless=true -cp $dir_jar Pd4Cmd \"$url\" $size_point_page $format_page $orientation $margins $adjustwidth $watermark $font_use $outfile";
		}
		//******************************************************************************************************
		//echo $cmdline;exit;
		shell_exec($cmdline);
		//******************************************************************************************************
		if (file_exists($fullpath_source)) { $lfiles_new[] = $fullpath_source; }
		if(file_exists($dir_tmp.$nomb_file_html)){
			unlink($dir_tmp.$nomb_file_html);//se elimina para actualizar el contenido del documento
		}
	}
	//**********************************************************************************************************
	if(count($lfiles_new) >= 1){
		$zip = new ZipArchive();
		$zipFileName = md5(time().uniqid()) . ".zip";
		$pathzip = sfConfig::get('sf_web_dir') . DIRECTORY_SEPARATOR . "tmp" . DIRECTORY_SEPARATOR . $zipFileName;
		//******************************************************************************************************
		if (file_exists($pathzip)) {
			unlink($pathzip);
		}
		//******************************************************************************************************
		if ($zip->open($pathzip, ZIPARCHIVE::CREATE) != TRUE) {
			die("Could not open archive");
		}
		//******************************************************************************************************
		foreach ($lfiles_new as $ifile) {
            if (file_exists($ifile)) {
				$zip->addFile($ifile, basename($ifile));
				//unlink($ifile);
            }
        }
		//******************************************************************************************************
		$zip->close();
		//******************************************************************************************************
		header("Content-Type: application/zip");
        header("Content-Disposition: attachment; filename=$zipFileName");
        header("Pragma: no-cache");
        header("Expires: 0");
        readfile("$pathzip");
        exit();
	}
	else
	{
		exit();
	}    
  }

  public function executeGenFuid()
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
    $dataUser  = UsuarioPeer::retrieveByPK($usuariologuiado);
    $base_path = sfConfig::get('base_simad');
	$this->setLayout(false);
	//*******************************************************************************************************
	$localizacionunidaddoc_id = $this->getRequestParameter('localizacionunidaddocumental_id');
	$dependencia_id = trim($this->getRequestParameter('dependencia_id')) ? trim($this->getRequestParameter('dependencia_id')) : $dataUser->getDependenciaId();
	$dependencia = DependenciaPeer::retrieveByPK($dependencia_id);
	//*******************************************************************************************************
	$dependencia = DependenciaPeer::retrieveByPK($dependencia_id);
	if($localizacionunidaddoc_id == 1){
		$modulo = "GESTION";
	}elseif($localizacionunidaddoc_id == 2){
		$modulo = "CENTRAL";
	}elseif($localizacionunidaddoc_id == 3){
		$modulo = "HISTORICO";
	}else{
		$modulo = "NONE";
	}
	//*******************************************************************************************************
    if(!$this->tienePrilegio("ARCHIVO_".$modulo."_GENERAR_FUID")){
        $this->redirect($base_path.'/no_autorizado.html');
    }
    //************************MANEJO PARA CREACION DIRECTORIO Y ARCHIVO A CONVERTIR**************************
    //sfConfig::get('sf_web_dir');    
