                            'logos_carnet/'.trim($dataUser->getRegional()->getEntidad()->getLogoCorporativo()) : $default_logo;
    
    //***************************************************************************************	
	$this->forward404Unless($this->unidad_documental);	
  }

  public function executeRearchivoPdf()
  {
