  public function executeEdit()
  {
    //$this->setLayout('layout-modal');
  	$this->nombre_funcion = "Editar";
    $this->unidad_documental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));
    $this->msgError=$this->getRequestParameter('msgError');
    $this->localizacion = $this->unidad_documental->getLocalizacionunidaddocumentalId();
    $this->name_localizacion = $this->unidad_documental->getLocalizacionunidaddocumental()->getDescripcion();
    //*******************************************************************************************************
	if($this->unidad_documental->getEstaCerrado()){
		$this->getUser()->setFlash('error_data', 'El expediente ya esta cerrado');
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$this->unidad_documental->getPrimaryKey().'&localizacionunidaddocumental_id='.$this->localizacion);
	}
	//*******************************************************************************************************
	if($this->localizacion == 1){
		$this->name_localizacion = "Gestion";
        $this->name_original = "Gestion";
		$this->permiso = 2;	
	}elseif($this->localizacion == 2){		
		$this->name_localizacion = "Central";
        $this->name_original = "Central";
		$this->permiso = 1;
	}elseif($this->localizacion == 3){
		$this->name_localizacion = "Historico";
		$this->name_original = "Historico";
		$this->permiso = 1;
	}
	/*********************OBTENER USUARIO DEL EXPEDIENTE***************************************/
    $c=new Criteria();
	$c->add(UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID, $this->getRequestParameter('unidaddocumental_id'));
    $respo = $this->UserUniDoc = UnidaddocumentalUsuarioPeer::doSelect($c);
    $this->UserUniDoc = new UnidaddocumentalUsuario();
    //*******************************************************************************************************
	foreach($respo as $res){
		if($res->getRolusuunidaddocId()== 1){			
			$this->udr_creador = $res->getUnidaddocumentalusuarioId();
			$this->creador = $res->getUsuarioId();
			$this->creador_name = $res->getUsuario()->getNombre()." ".$res->getUsuario()->getApellido();
		}elseif($res->getRolusuunidaddocId()== 2){
			$this->udr_responsable = $res->getUnidaddocumentalusuarioId();
			$this->responsable = $res->getUsuarioId();
		}elseif($res->getRolusuunidaddocId()== 3){
			$this->udr_inventariador = $res->getUnidaddocumentalusuarioId();
			$this->inventariador = $res->getUsuarioId();
		}
	}
	/*********************OBTENER EL LA TRD DEL EXPEDIENTE***************************************/
	$this->dependencia_select = "";
	$subserie = SubseriePeer::retrieveByPk($this->unidad_documental->getSubserieId());
	$serie_id = $subserie->getSerieId();
	$dependencia_id = $subserie->getSerie()->getDependenciaId();
	/*********************OBTENER EL PARAMETRO PARA EL MANEJO DE TRD*****************************/
	$param_factory = ParametroPeer::retrieveByPK(61);
	$param_trd = $param_factory->getValornumerico();
	/********************************************************************************************/
	$this->tipo_manejo_trd = $param_trd;//parametro manejo de TRD 1=por dependencia, 2=por procesos
	$this->form_tag = 2;//si es consulta o creacion	
	/********************************************************************************************/
	$this->dependencias = DependenciaPeer::getDependenciaPorArchivo($this->permiso, $this->form_tag, $param_trd);
	$this->series_list = $this->getSeriesList($dependencia_id);
	$this->subseries_list = $this->getSubseriesList($serie_id);
	//********************************************************************************************
	$list_inteIds = array();$list_names = array();
	foreach (UnidadDocumentalPeer::getListIntersadosByComId($this->unidad_documental->getPrimaryKey()) as $interesado) {
		$list_inteIds[] = $interesado->getInteresados()->getPrimaryKey();
		$list_names[] = trim($interesado->getInteresados()->getNumeroIdentificacion())." - ".trim($interesado->getInteresados()->getNombre());
	}
	//********************************************************************************************
	$this->pkInteresados = $list_inteIds;
	$this->intesadosNames = $list_names;
	//********************************************************************************************/
	$this->dependencia_select = $dependencia_id;
	$this->serie_select = $serie_id;
	$this->subserie_select = $this->unidad_documental->getSubserieId();
	$this->is_display = 'style="display: none;"';
    $this->localizacion_object = LocalizacionUnidadDocumentalPeer::retrieveByPK($this->localizacion);
	//********************************************************************************************/
	$this->regionales = RegionalPeer::getOrdenRegional();
    $this->regional_select = $this->unidad_documental->getRegionalId();;
	//********************************************************************************************/
	$this->forward404Unless($this->unidad_documental);
  }

  public function executeReopenExp()
  {
    //$this->setLayout('layout-modal');
  	$this->nombre_funcion = "Reabrir Expediente";
    $expediente_original = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));
    $this->msgError=$this->getRequestParameter('msgError');
    $this->localizacion = $this->unidad_documental->getLocalizacionunidaddocumentalId();
    $this->name_localizacion = $this->unidad_documental->getLocalizacionunidaddocumental()->getDescripcion();
    //*******************************************************************************************************
	if(empty($this->unidad_documental->getEstaCerrado())){
		$this->getUser()->setFlash('error_data', 'El expediente debe estar cerrado');
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$this->unidad_documental->getPrimaryKey().'&localizacionunidaddocumental_id='.$this->localizacion);
	}
	//*******************************************************************************************************
	if($this->localizacion == 1){
		$this->name_localizacion = "Gestion";
        $this->name_original = "Gestion";
		$this->permiso = 2;
		$currentForm   = "ARCHIVO_GESTION_REABRIR_EXPEDIENTE";
	}elseif($this->localizacion == 2){		
		$this->name_localizacion = "Central";
        $this->name_original = "Central";
		$this->permiso = 1;
		$currentForm   = "ARCHIVO_CENTRAL_REABRIR_EXPEDIENTE";
	}elseif($this->localizacion == 3){
		$this->name_localizacion = "Historico";
		$this->name_original = "Historico";
		$this->permiso = 1;
		$currentForm   = "ARCHIVO_HISTORICO_REABRIR_EXPEDIENTE";
	}
	//*******************************************************************************************************
	if(!$this->tienePrilegio($currentForm)){
		$this->redirect('/no_autorizado.html');
	}
	//*******************************************************************************************************
    $c = new Criteria();
	$c->add(UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID, $this->getRequestParameter('unidaddocumental_id'));
    $respo = $this->UserUniDoc = UnidaddocumentalUsuarioPeer::doSelect($c);
    $this->UserUniDoc = new UnidaddocumentalUsuario();
    //*******************************************************************************************************
	foreach($respo as $res){
		if($res->getRolusuunidaddocId()== 1){			
			$this->udr_creador = $res->getUnidaddocumentalusuarioId();
			$this->creador = $res->getUsuarioId();
			$this->creador_name = $res->getUsuario()->getNombre()." ".$res->getUsuario()->getApellido();
		}elseif($res->getRolusuunidaddocId()== 2){
			$this->udr_responsable = $res->getUnidaddocumentalusuarioId();
			$this->responsable = $res->getUsuarioId();
		}elseif($res->getRolusuunidaddocId()== 3){
			$this->udr_inventariador = $res->getUnidaddocumentalusuarioId();
			$this->inventariador = $res->getUsuarioId();
		}
	}
	/*********************OBTENER EL LA TRD DEL EXPEDIENTE***************************************/
	$this->dependencia_select = "";
	$subserie = SubseriePeer::retrieveByPk($this->unidad_documental->getSubserieId());
	$serie_id = $subserie->getSerieId();
	$dependencia_id = $subserie->getSerie()->getDependenciaId();
	/*********************OBTENER EL PARAMETRO PARA EL MANEJO DE TRD*****************************/
	$param_factory = ParametroPeer::retrieveByPK(61);
	$param_trd = $param_factory->getValornumerico();
	/********************************************************************************************/
	$this->tipo_manejo_trd = $param_trd;//parametro manejo de TRD 1=por dependencia, 2=por procesos
	$this->form_tag = 2;//si es consulta o creacion	
	/********************************************************************************************/
	$this->dependencias = DependenciaPeer::getDependenciaPorArchivo($this->permiso, $this->form_tag, $param_trd);
	$this->series_list = $this->getSeriesList($dependencia_id);
	$this->subseries_list = $this->getSubseriesList($serie_id);
	//********************************************************************************************/
	$this->dependencia_select = $dependencia_id;
	$this->serie_select = $serie_id;
	$this->subserie_select = $this->unidad_documental->getSubserieId();
	$this->is_display = 'style="display: none;"';
    $this->localizacion_object = LocalizacionUnidadDocumentalPeer::retrieveByPK($this->localizacion);
	//********************************************************************************************/
	$this->regionales = RegionalPeer::getOrdenRegional();
    $this->regional_select = $this->unidad_documental->getRegionalId();;
	//********************************************************************************************/
	$this->forward404Unless($this->unidad_documental);
  }

  public function executeUpdate()
  {
    if (!$this->getRequestParameter('unidaddocumental_id'))
    {
      $unidad_documental = new UnidadDocumental();
	  //**********************************************************************************************************************
	  $unidad_documental_anterior = clone $unidad_documental;
	  //**********************************************************************************************************************
      $unidad_documental->setEstadotransferencia(0);
      $unidad_documental->setFechaCreacion(date('Y-m-d G:i:s'));
      $codigo_barras = trim($this->getRequestParameter('codigo_barras')) ? trim($this->getRequestParameter('codigo_barras')) : "";
      $origen = 0;
    }
    else
    {
      $unidad_documental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));
      //**********************************************************************************************************************
	  $unidad_documental_anterior = clone $unidad_documental;
	  //**********************************************************************************************************************
      $origen = 1;
      $codigo_barras = trim($this->getRequestParameter('codigo_barras')) ? trim($this->getRequestParameter('codigo_barras')) : trim($unidad_documental->getCodigoBarras());
      $this->forward404Unless($unidad_documental);
    }
	//************************************************************************************************************************
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$id_responsable = trim($this->getRequestParameter('id_responsable')) ? trim($this->getRequestParameter('id_responsable')) : $usuariologuiado;
	$id_creador = trim($this->getRequestParameter('id_creador')) ? trim($this->getRequestParameter('id_creador')) : $usuariologuiado;
	$id_inventariador = trim($this->getRequestParameter('id_inventariador')) ? trim($this->getRequestParameter('id_inventariador')) : $usuariologuiado;
	//************************************************************************************************************************
    $localizacion = $this->getRequestParameter('id_localizacion');
    $usuario_responsable = UsuarioPeer::retrieveByPK($id_responsable);
	$volumen = trim($this->getRequestParameter('volumen')) ? trim($this->getRequestParameter('volumen')) : 1;
	//************************************************************************************************************************
    $unidad_documental->setLocalizacionunidaddocumentalId($localizacion);
    $unidad_documental->setSoporteunidaddocumentalId($this->getRequestParameter('soporteunidaddocumental_id') ? $this->getRequestParameter('soporteunidaddocumental_id') : null);
    $unidad_documental->setEstadounidaddocumentalId($this->getRequestParameter('estadounidaddocumental_id') ? $this->getRequestParameter('estadounidaddocumental_id') : null);
    $unidad_documental->setFrecuenciaconsultaId($this->getRequestParameter('frecuenciaconsulta_id') ? $this->getRequestParameter('frecuenciaconsulta_id') : null);
    $unidad_documental->setUnidadconservadoraId($this->getRequestParameter('unidadconservadora_id') ? $this->getRequestParameter('unidadconservadora_id') : null);
    $unidad_documental->setSubserieId($this->getRequestParameter('subserie_id') ? $this->getRequestParameter('subserie_id') : null);
    $unidad_documental->setRegionalId($usuario_responsable->getRegionalId());
	$unidad_documental->setTitulo(trim($this->getRequestParameter('titulo')));
    $unidad_documental->setContenido(trim($this->getRequestParameter('contenido')));
    $unidad_documental->setCreadoPorWeb(1);
    $unidad_documental->setFolios(trim($this->getRequestParameter('folios')));
    $unidad_documental->setNotas(trim($this->getRequestParameter('notas')));
    $unidad_documental->setVolumen(trim($this->getRequestParameter('volumen')) ? trim($this->getRequestParameter('volumen')) : 1);
	$unidad_documental->setNumeroCaja(trim($this->getRequestParameter('numero_caja')) ? trim($this->getRequestParameter('numero_caja')) : null);
	$unidad_documental->setNumeroCarpeta(trim($this->getRequestParameter('numero_carpeta')) ? trim($this->getRequestParameter('numero_carpeta')) : null);
    $unidad_documental->setGeoBodega(trim($this->getRequestParameter('geo_bodega')) ? trim($this->getRequestParameter('geo_bodega')) : null);
    $unidad_documental->setGeoCuerpo(trim($this->getRequestParameter('geo_cuerpo')) ? trim($this->getRequestParameter('geo_cuerpo')) : null);
    $unidad_documental->setGeoTorre(trim($this->getRequestParameter('geo_torre')) ? trim($this->getRequestParameter('geo_torre')) : null);
    $unidad_documental->setGeoPiso(trim($this->getRequestParameter('geo_piso')) ? trim($this->getRequestParameter('geo_piso')) : null);
    $unidad_documental->setRepositorioOrigen(trim($this->getRequestParameter('repositorio_origen')) ? trim($this->getRequestParameter('repositorio_origen')) : null);
    $unidad_documental->setNumeroIdentificacion(trim($this->getRequestParameter('numero_identificacion')) ? trim($this->getRequestParameter('numero_identificacion')) : null);
    //************************************************************************************************************************    
    if ($this->getRequestParameter('fecha_llegada')){
    	try{
    		$date = new DateTime($this->getRequestParameter('fecha_llegada'));
    		$unidad_documental->setFechaLlegada($date->format('Y-m-d'));
    	}catch (Exception $ex){}
    }    
    //************************************************************************************************************************
	// capturar tiempos para retencion
	$subserie = SubseriePeer::retrieveByPK($this->getRequestParameter('subserie_id'));
	$paramentro_tvd = ParametroPeer::retrieveByPK(33);
	$fecha_tvd = $paramentro_tvd->getValortexto();
	//************************************************************************************************************************
	$idIsCodeBar = false;
    if($codigo_barras){
      $unidad_documental->setCodigoBarras($codigo_barras);
    }elseif(1!=1){
      $codigo_barras = str_pad($this->getNewCodigoBarras(),7,0);
      $unidad_documental->setCodigoBarras($codigo_barras);
    }else{
		$idIsCodeBar = true;
	}
    //************************************************************************************************************************
    if ($this->getRequestParameter('fecha_apertura')){
    	try{
    		$date = new DateTime($this->getRequestParameter('fecha_apertura'));
    		$unidad_documental->setFechaApertura($date->format('Y-m-d'));
    	}catch (Exception $ex){}
    } 
    //************************************************************************************************************************
    if ($this->getRequestParameter('fecha_cierre')){
    	try{
    		$date = new DateTime($this->getRequestParameter('fecha_cierre'));
    		$unidad_documental->setFechaCierre($date->format('Y-m-d'));
    	}catch (Exception $ex){}
    } 
    //************************************************************************************************************************
	$tiempo_retencion = 0;$campo_vencimiento = date("Y-m-d");
    if($localizacion == 1){
    	$campo_vencimiento = $this->getRequestParameter('fecha_apertura');
    	$unidad_documental->setUbicacionengestion($this->getRequestParameter('ubicacionengestion'));
    	if($this->getRequestParameter('fecha_apertura') <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnGestion();
		}
    }elseif($localizacion == 2){
    	$campo_vencimiento = $this->getRequestParameter('fecha_cierre');
		$unidad_documental->setUbicacionencentral($this->getRequestParameter('ubicacionencentral'));
		if($this->getRequestParameter('fecha_cierre') <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnCentral();
		}
    }elseif($localizacion == 3){
    	$campo_vencimiento = $this->getRequestParameter('fecha_cierre');
		$unidad_documental->setUbicacionenhistorico($this->getRequestParameter('ubicacionenhistorico'));
		if($this->getRequestParameter('fecha_cierre') <= $fecha_tvd){
    		$tiempo_retencion = $subserie->getAnosValoracionDocumental();
    	}else{
			$tiempo_retencion = $subserie->getAnosEnHistorico();
    	}
	}
    ///////////// FECHA DE VENCIMIENTO CON TABLAS DE RETENCION DOCUMENTAL
    //************************************************************************************************************************
    try{
		$fecha = new DateTime($campo_vencimiento);
        if(is_numeric($tiempo_retencion)){
            $fecha->add(new DateInterval('P'.$tiempo_retencion.'Y'));
        }
		$unidad_documental->setFechavencimiento($fecha->format('Y-m-d'));
	}catch (Exception $ex){
        list($d, $m, $y) = sfI18N::getDateForCulture($campo_vencimiento, $this->getUser()->getCulture());
        $fecha   = AddYears(date("Y-m-d"),$tiempo_retencion);
        $unidad_documental->setFechavencimiento($fecha);
	}
    //************************************************************************************************************************
    ////////////// FIN FECHA VENCIMIENTO //////////////////////
    //verificar que el codigo de barras y volumen no se repitan combinando los dos	    
    if (trim($this->getRequestParameter('unidaddocumental_id'))){
	    $resp  = $this->validarCodigoEdit($codigo_barras,$volumen,$unidad_documental->getPrimaryKey());	
	}elseif(!$idIsCodeBar){
		$resp  = $this->validarCodigo($codigo_barras,$volumen);		
	}
    //************************************************************************************************************************
    if($resp == 0){	
		$unidad_documental->save();
	    //********************************************************************************************************************
		if($idIsCodeBar){ 
			$unidad_documental->setCodigoBarras($unidad_documental->getPrimaryKey());
			$unidad_documental->save();
		}
		//********************************************************************************************************************
	    $this->guardarAuditoria($unidad_documental_anterior,$unidad_documental);
		//********************************************************************************************************************
	    // MANEJO DE UNIDAD DOC USUARIO
	    $this->executeUserUniDocRole(1, $id_creador,$unidad_documental->getPrimaryKey(),trim($this->getRequestParameter('udr_creador')));
		$this->executeUserUniDocRole(2, $id_responsable,$unidad_documental->getPrimaryKey(),trim($this->getRequestParameter('udr_responsable')));
		$this->executeUserUniDocRole(3, $id_inventariador,$unidad_documental->getPrimaryKey(), trim($this->getRequestParameter('udr_inventariador')));
		//*******************************************************************************************************************
		$list_interesado = preg_split("/[,]+/", trim($this->getRequestParameter('idUserInteresados')));
		for($index=0; $index < count($list_interesado); $index++) {
			$isAddInteresado = UnidaddocumentalInteresadosPeer::addNewInteresadoByComId($unidad_documental->getPrimaryKey(),$list_interesado[$index]);
		}
		$isDeleteNotIn = UnidaddocumentalInteresadosPeer::deleteByComIdNotExist($unidad_documental->getPrimaryKey(),$list_interesado);
		//*******************************************************************************************************************
		$coll_metadatos = MetadatosSubseriePeer::getListMetadatosBySubserie($subserie->getPrimaryKey());
		foreach($coll_metadatos as $metadato){
			$name_input = md5($metadato->getMetaDatos()->getPrimaryKey().$metadato->getMetaDatos()->getNombre());
			if(trim($this->getRequestParameter($name_input))){
				$info_field = array();
				$info_field['usuario_id'] = $usuariologuiado;
				$info_field['metadato_id'] = $metadato->getMetaDatos()->getPrimaryKey();
				$info_field['unidaddocumental_id'] = $unidad_documental->getPrimaryKey();
				$info_field['value_metadato'] = trim($this->getRequestParameter($name_input));
				$info_field['fecha_creacion'] = date("Y-m-d G:i:s");
				$isCreate = MetadatosExpedientePeer::addNewMetadatoExpediente($info_field);
			}
		}
		//*******************************************************************************************************************
		if(trim($this->getRequestParameter('backselect'))){
			$comrecibida_id = trim($this->getRequestParameter('comrecibida_id'));
			return $this->redirect($this->getRequest()->getScriptName().'/transferencia/resultado?comrecibida_id='.$comrecibida_id.'&unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&destinotransferencia_id='.$localizacion);
		}
		//*******************************************************************************************************************
	    if ($this->getRequestParameter('unidaddocumental_id')){
	      	return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$localizacion);
	    }else{
	    	//return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$localizacion);
	      	return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/showCrear?unidaddocumental_id='.$unidad_documental->getPrimaryKey().'&localizacion='.$localizacion);		
	    }
 	}else{
		if ($this->getRequestParameter('unidaddocumental_id')){
	         return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/edit?localizacion='.$localizacion."&unidaddocumental_id=".$this->getRequestParameter('unidaddocumental_id')."&msgError=1");	
		}else{
			return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/create?localizacion='.$localizacion."&msgError=1");		
		}
	}    
  }
  
  public function guardarAuditoria($anterior,$nueva)
  {
    $usuariologuiado = $this->getUser()->getAttribute('usuario_id','', 'subscriber');
    AuditLogPeer::guardarAuditoriaLite("UnidadDocumental",$anterior,$nueva,ModulesEnable::Archivo,$nueva->getCodigoBarras(),$usuariologuiado);
  }
  
  public function validarCodigo($codigo_barras, $volumen)
  {  	
	$c = new Criteria();
	$c->add(UnidadDocumentalPeer::CODIGO_BARRAS,$codigo_barras);
	//$c->add(UnidadDocumentalPeer::VOLUMEN,$volumen);
    //$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID,4,Criteria::NOT_EQUAL);
	$resp = UnidadDocumentalPeer::doCount($c);
	if($resp == null){		
		return 0;
	}else{		
		return 1;
	}		
  }
  
  public function validarCodigoEdit($codigo_barras, $volumen, $pk)
  {  	
	$c = new Criteria();
	$c->add(UnidadDocumentalPeer::CODIGO_BARRAS,$codigo_barras);
	//$c->add(UnidadDocumentalPeer::VOLUMEN,$volumen);
	$c->add(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,$pk,Criteria::NOT_EQUAL);
    $c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID,4,Criteria::NOT_EQUAL);
	$resp = UnidadDocumentalPeer::doCount($c);
	if($resp == null){		
		return 0;
	}else{		
		return 1;
	}		
  }    
    
    public function executeReporteDescarte()
    {
  	$this->setLayout(false);
  	$c = new Criteria();
    $c->setDistinct();
	$parametros_consulta = "";	
	// CONSULTA POR LOCALIZACION
	$localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
    $usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if($localizacion != ""){
		$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID, $localizacion);
		$parametros_consulta .= "&localizacionunidaddocumental_id=".$localizacion;		
	}
	
	// CONSULTA POR SOPORTE
	$soporte = $this->getRequestParameter('soporteunidaddocumental_id');
	if($soporte != ""){
		$c->add(UnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID, $soporte);
		$parametros_consulta .= "&soporteunidaddocumental_id=".$soporte;		
	}
	
	// CONSULTA POR ESTADO
	$estado = $this->getRequestParameter('estadounidaddocumental_id');
	if($estado != ""){
		$c->add(UnidadDocumentalPeer::ESTADOUNIDADDOCUMENTAL_ID, $estado);
		$parametros_consulta .= "&estadounidaddocumental_id=".$estado;		
	}
	
    // CONSULTA POR MARCA
	$marca = $this->getRequestParameter('marcado');
	if($marca != ""){
		$c->add(UnidadDocumentalPeer::MARCA, $usuario_conectado);
		$parametros_consulta .= "&marcado=".$usuario_conectado; 		
	}
    
	// CONSULTA FRECUENCIA DE CONSULTA
	$frecuencia_consulta = $this->getRequestParameter('frecuenciaconsulta_id');
	if($frecuencia_consulta != ""){
		$c->add(UnidadDocumentalPeer::FRECUENCIACONSULTA_ID, $frecuencia_consulta);
		$parametros_consulta .= "&frecuenciaconsulta_id=".$frecuencia_consulta; 		
	}
	
	// CONSULTA CODIGO DE REMISION
	$codigo_remision = $this->getRequestParameter('numero_remision');
	if($codigo_remision != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$c->add(ContenidoUnidadDocumentalPeer::CONTENIDOUNIDADDOCUMENTAL_ID,$codigo_remision);
		$parametros_consulta .= "&numero_remision=".$codigo_remision;		
	}
	
	// CONSULTA UNIDAD CONSERVADORA
	$unidad_conservadora = $this->getRequestParameter('unidadconservadora_id');
	if($unidad_conservadora != ""){
		$c->add(UnidadDocumentalPeer::UNIDADCONSERVADORA_ID, $unidad_conservadora);
		$parametros_consulta .= "&unidadconservadora_id=".$unidad_conservadora;		
	}
	
	//CONSULTA POR DEPENDENCIA
	$dependencia_select = $this->getRequestParameter('dependencia_id');
	if($dependencia_select != ""){
	    $c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePeer::SUBSERIE_ID);
      $c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
		  $c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
      $c->add(DependenciaPeer::DEPENDENCIA_ID,$dependencia_select);      
		  $parametros_consulta .= "&dependencia_id=".$dependencia_select;			
	}
	
	// CONSULTA SUBSERIE
	$subserie = $this->getRequestParameter('subserie_id');
	if($subserie != ""){
		$c->add(UnidadDocumentalPeer::SUBSERIE_ID, $subserie);
