	}
	
	// CONSULTA VENCIDOS
	$fecha_vencimiento = $this->getRequestParameter('vencidos');
	if($fecha_vencimiento != ""){
		$fecha_actual = date('Y-m-d');
		$c->add(UnidadDocumentalPeer::FECHAVENCIMIENTO, $fecha_actual, Criteria::LESS_EQUAL);
		$parametros_consulta .= "&vencidos=".$fecha_vencimiento;	
	}
	
	// CONSULTA MARCADOS PARA ELIMINACION
	$marca_eliminacion = $this->getRequestParameter('exp_eliminacion');
	if($marca_eliminacion != ""){
		$c->add(UnidadDocumentalPeer::MARCA_ELIMINACION, NULL, Criteria::ISNOTNULL);
		$parametros_consulta .= "&exp_eliminacion=".$marca_eliminacion;
	}
	
	// CONSULTA OBSERVACIONES DE ELIMINACION
	$obs_eliminacion = $this->getRequestParameter('obs_eliminacion');
	if($obs_eliminacion != ""){
		$c->add(UnidadDocumentalPeer::OBS_ELIMINACION, '%'.$obs_eliminacion.'%', Criteria::LIKE);
		$parametros_consulta .= "&obs_eliminacion=".$obs_eliminacion;
	}
	
	// CONSULTA TITULO
	$titulo = $this->getRequestParameter('titulo');
