		$cad_titulo = str_replace('|','%',$this->getRequestParameter('titulo'));
		$c->add(UnidadDocumentalPeer::TITULO, '%'.$cad_titulo.'%', Criteria::LIKE);
		$parametros_consulta .= "&titulo=".$cad_titulo;	
	}
	
	// CONSULTA CREADO POR WEB
	$creado_web = $this->getRequestParameter('creado_por_web');
	if($creado_web != ""){
		$c->add(UnidadDocumentalPeer::CREADO_POR_WEB, $creado_web);	
