	// CONSULTA UBICACION EN GESTION
	$ubicacion_gestion = $this->getRequestParameter('ubicacionengestion');
	if($ubicacion_gestion != ""){
		$c->add(UnidadDocumentalPeer::UBICACIONENGESTION, '%'.$ubicacion_gestion.'%', Criteria::LIKE);
		$parametros_consulta .= "&ubicacionengestion=".$ubicacion_gestion;		
	}
	
	// CONSULTA UBICACION EN CENTRAL
	$ubicacion_central = $this->getRequestParameter('ubicacionencentral');
	if($ubicacion_central != ""){
		$c->add(UnidadDocumentalPeer::UBICACIONENCENTRAL, '%'.$ubicacion_central.'%', Criteria::LIKE);
		$parametros_consulta .= "&ubicacionencentral=".$ubicacion_central;		
	}
	
	// CONSULTA UBICACION EN HISTORICO
	$ubicacion_historico = $this->getRequestParameter('ubicacionenhistorico');
	if($ubicacion_historico != ""){
		$c->add(UnidadDocumentalPeer::UBICACIONENHISTORICO, '%'.$ubicacion_historico.'%', Criteria::LIKE);
		$parametros_consulta .= "&ubicacionenhistorico=".$ubicacion_historico;		
	}
	
     //consulta expedientes sin ubicacion        
    if($this->getRequestParameter('sin_ubicacion')?'1':'0'){        
      switch($localizacion){
        case 1;
             $c->add(UnidadDocumentalPeer::UBICACIONENGESTION, '');
        break;
        case 2;
             $c->add(UnidadDocumentalPeer::UBICACIONENCENTRAL, '');
        break;
        case 3;
             $c->add(UnidadDocumentalPeer::UBICACIONENHISTORICO, '');
        break;
      }	
      $parametros_consulta .= "&sin_ubicacion=".$this->getRequestParameter('sin_ubicacion');			
	}else{
	   //echo 'no';
	} 
    
	// CONSULTA FOLIOS
	$folios = $this->getRequestParameter('folios');
	if($folios != ""){
		$c->add(UnidadDocumentalPeer::FOLIOS, $folios);	
		$parametros_consulta .= "&folios=".$folios;	
	}
	
	// CONSULTA FECHA CREACION
	$fecha_creacion_inicial = $this->getRequestParameter('fecha_creacion_inicial');
	$fecha_creacion_final = $this->getRequestParameter('fecha_creacion_final');
	if($fecha_creacion_inicial != ""){
		if($fecha_creacion_final == ""){
			$fecha_creacion_final = $fecha_creacion_inicial;
		}
		$c->add(UnidadDocumentalPeer::FECHA_CREACION, $fecha_creacion_inicial.' 00:00:00', Criteria::GREATER_EQUAL);
		$c->addAnd(UnidadDocumentalPeer::FECHA_CREACION, $fecha_creacion_final.' 23:59:59', Criteria::LESS_EQUAL);
		$parametros_consulta .= "&fecha_creacion_inicial=".$fecha_creacion_inicial;
		$parametros_consulta .= "&fecha_creacion_final=".$fecha_creacion_final;		
	}
	
	// CONSULTA NOTAS
	$notas = $this->getRequestParameter('notas');
	if($notas != ""){
		$c->add(UnidadDocumentalPeer::NOTAS, '%'.$notas.'%', Criteria::LIKE);
		$parametros_consulta .= "&notas=".$notas;		
	}
	
	// CONSULTA FECHA VENCIMIENTO    
	$fecha_vencimiento_inicial = $this->getRequestParameter('fechavencimiento');
	$fecha_vencimiento_final = $this->getRequestParameter('fecha_vencimiento_final');
	
	if($fecha_vencimiento_inicial != ""){	   
		$c->add(UnidadDocumentalPeer::FECHAVENCIMIENTO, $fecha_vencimiento_inicial, Criteria::GREATER_EQUAL);
		$parametros_consulta .= "&fechavencimiento=".str_replace("/","-",$fecha_vencimiento_inicial);		
	}
    if($fecha_vencimiento_final != ""){	        
		$c->addAnd(UnidadDocumentalPeer::FECHAVENCIMIENTO, $fecha_vencimiento_final, Criteria::LESS_EQUAL);		
		$parametros_consulta .= "&fecha_vencimiento_final=".str_replace("/","-",$fecha_vencimiento_final);			
	}
		    	
	if($fecha_vencimiento_final == "" && $fecha_vencimiento_inicial == ""){
	   $c->addAnd(UnidadDocumentalPeer::FECHAVENCIMIENTO, date("Y-m-d").' 23:59:59', Criteria::LESS_EQUAL);
	}
	// CONSULTA VOLUMEN
	$volumen = $this->getRequestParameter('volumen');
	if($volumen != ""){
		$c->add(UnidadDocumentalPeer::VOLUMEN, $volumen);
		$parametros_consulta .= "&volumen=".$volumen;		
	}
	
	// CONSULTA CREADO POR
	$creado_por = $this->getRequestParameter('id_creador');
	if($creado_por != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		$c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID, $creado_por);
		$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID, 1);
		$parametros_consulta .= "&id_creador=".$creado_por;			
	}
	
	// CONSULTA INVENTARIADO POR
	$inventariado = $this->getRequestParameter('id_inventariador');
	if($inventariado != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		$c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID, $inventariado);
		$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID, 2);
		$parametros_consulta .= "&id_inventariador=".$inventariado;			
	}
	
	// CONSULTA RESPONSABLE POR
	$responsable = $this->getRequestParameter('id_responsable');
	if($responsable != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		$c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID, $responsable);
		$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID, 3);
		$parametros_consulta .= "&id_responsable=".$responsable;			
	}
	
	if($localizacion == 1){
		$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		if(!$this->tienePrilegio("VER_TODAS_LAS_SUBSERIES")){
		  $c->add(UnidaddocumentalUsuarioPeer::USUARIO_ID,$usuario_conectado);
		  }
		$c->add(UnidaddocumentalUsuarioPeer::ROLUSUUNIDADDOC_ID,1);
	}
	
	// CONSULTA RESPONSABLE POR
	$imagen_contiene = $this->getRequestParameter('imagen_contiene');
	if($imagen_contiene != ""){
		$c->addJoin(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$c->add(ContenidoUnidadDocumentalPeer::DESCRIPCION, '%'.$imagen_contiene.'%', Criteria::LIKE);
		$parametros_consulta .= "&imagen_contiene=".$imagen_contiene;			
	}
    //CONSULTA CON DOCUMENTOS
	$contiene_doc = $this->getRequestParameter('con_documentos');	
	if($contiene_doc == "1"){
		$sql = sprintf("%s IN (SELECT %s FROM %s)",UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::TABLE_NAME);
    	$aux = $c->getNewCriterion(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $sql, Criteria::CUSTOM);
		//$c->add(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $sql, Criteria::CUSTOM);
    	$c->add($aux);
		$parametros_consulta .= "&con_documentos=".$contiene_doc;
	}elseif($contiene_doc == "0"){
		$sql = sprintf("%s NOT IN (SELECT %s FROM %s)",UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID,ContenidoUnidadDocumentalPeer::TABLE_NAME);
    	$aux = $c->getNewCriterion(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $sql, Criteria::CUSTOM);
		//$c->add(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $sql, Criteria::CUSTOM);
    	$c->add($aux);
		$parametros_consulta .= "&con_documentos=".$contiene_doc;
	}
	//********************************************************************************************************************
	$field_orden = !empty($this->getRequestParameter('orden')) ? trim($this->getRequestParameter('orden')) : 0;
	$tipo_orden = !empty($this->getRequestParameter('tipo_orden')) ? trim($this->getRequestParameter('tipo_orden')) : 0;
  	if(!empty($field_orden)){
		$query_order = sprintf("%s.%s",UnidadDocumentalPeer::TABLE_NAME,$field_orden);
  		if($tipo_orden == 1){
  			$c->addAscendingOrderByColumn($query_order);
  			$parametros_consulta.="&tipo_orden=".$tipo_orden;
  		}elseif($tipo_orden == 2){
  			$c->addDescendingOrderByColumn($query_order);
  			$parametros_consulta.="&tipo_orden=".$tipo_orden;
  		}else{
  			$c->addDescendingOrderByColumn($query_order);
  			$parametros_consulta.="&tipo_orden=".$tipo_orden;
  		}
  		$parametros_consulta .= "&orden=".$field_orden;
  	}else{
  		if($tipo_orden == 1){
  			$c->addAscendingOrderByColumn(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
  			$parametros_consulta.="&tipo_orden=".$tipo_orden;
  		}elseif($tipo_orden == 2){
  			$c->addDescendingOrderByColumn(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
  			$parametros_consulta.="&tipo_orden=".$tipo_orden;
  		}else {
  			$c->addDescendingOrderByColumn(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
  		}
  	}	
    //*****************************Consulta por tipos de descarte**********************************************************
    $tipodescarte = $this->getRequestParameter('tipodescarte');
    if(trim($tipodescarte) != ""){
        $parametros_consulta.="&tipodescarte=".$tipodescarte;
        $contador = 0;
        $d = new Criteria();
        $disposicion_final = DescarteFinalSubseriePeer::doSelect($d);
        foreach($disposicion_final as  $descarte_final){
            $nombre_campo = $descarte_final->getPrimaryKey().'_'.mb_strtolower(str_replace(" ","_",$descarte_final->getDescripcion()));
            if($this->getRequestParameter($nombre_campo)?'1':'0'){
                if($contador >= 1){
                   $c->addOr(DescartePorSubseriePeer::DESCARTEFINALSUBSERIE_ID, $this->getRequestParameter($nombre_campo)); 
                }else{
                   $c->addAnd(DescartePorSubseriePeer::DESCARTEFINALSUBSERIE_ID, $this->getRequestParameter($nombre_campo));
                }
                $contador++; 
            }
        }
		//****************************************************************************************************************
        if($contador){
           $c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID, DescartePorSubseriePeer::SUBSERIE_ID); 
        }
    }
    //********************************************************************************************************************
	$c->addAscendingOrderByColumn(UnidadDocumentalPeer::CODIGO_BARRAS);
    	
  	$this->username = $this->getUser()->getAttribute('username', '', 'subscriber');
  	$c->clearSelectColumns();  	
  	$c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePeer::SUBSERIE_ID);
  	$c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
    //$c->addJoin(SubseriePeer::SUBSERIE_ID,DescartePorSubseriePeer::SUBSERIE_ID);
    //$c->addJoin(DescartePorSubseriePeer::DESCARTEFINALSUBSERIE_ID,DescarteFinalSubseriePeer::DESCARTEFINALSUBSERIE_ID);
  	$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
  	$c->addJoin(UnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID,SoporteUnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID);            
  	//***************************************************************************************************
    $c->addSelectColumn(UnidadDocumentalPeer::CODIGO_BARRAS);//0
  	$c->addSelectColumn(UnidadDocumentalPeer::TITULO);//1
  	$c->addSelectColumn(UnidadDocumentalPeer::FECHA_APERTURA);//2
  	$c->addSelectColumn(UnidadDocumentalPeer::FECHA_CIERRE);//3
  	$c->addSelectColumn(DependenciaPeer::NOMBRE);//4
  	$c->addSelectColumn(SeriePeer::DESCRIPCION);//5
  	$c->addSelectColumn(SubseriePeer::DESCRIPCION);//6
  	$c->addSelectColumn(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);//7
  	$c->addSelectColumn(UnidadDocumentalPeer::FOLIOS);//8
  	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENCENTRAL);//9
  	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENGESTION);//10
  	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENHISTORICO);//11
  	$c->addSelectColumn(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID);//12
	$c->addSelectColumn(SoporteUnidadDocumentalPeer::DESCRIPCION);//13
    $c->addSelectColumn(UnidadDocumentalPeer::FECHAVENCIMIENTO);//14
    //$c->addSelectColumn(DescarteFinalSubseriePeer::DESCRIPCION);//15
    $c->addSelectColumn(UnidadDocumentalPeer::SUBSERIE_ID);//15
	$this->resultset = UnidadDocumentalPeer::doSelectStmt($c);
	}
    
     
    public function executeExportar()
	{
      	$this->setLayout(false);
     	//******************************************************************************************************************
     	$c = new Criteria();
     	$c = $this->getBasicCriteria();
     	$localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
     	$parametros_consulta = "";
    	//******************************************************************************************************************
      	$this->username = $this->getUser()->getAttribute('username', '', 'subscriber');
      	$c->clearSelectColumns();  	
      	$c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePeer::SUBSERIE_ID);
      	$c->addJoin(SubseriePeer::SERIE_ID,SeriePeer::SERIE_ID);
      	$c->addJoin(SeriePeer::DEPENDENCIA_ID,DependenciaPeer::DEPENDENCIA_ID);
      	$c->addJoin(UnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID,SoporteUnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID);
		//*****************************************************************************************************************
      	$c->addSelectColumn(UnidadDocumentalPeer::CODIGO_BARRAS);//0
      	$c->addSelectColumn(UnidadDocumentalPeer::TITULO);//1
      	$c->addSelectColumn(UnidadDocumentalPeer::FECHA_APERTURA);//2
      	$c->addSelectColumn(UnidadDocumentalPeer::FECHA_CIERRE);//3	
      	$c->addSelectColumn(DependenciaPeer::NOMBRE);//4
      	$c->addSelectColumn(SeriePeer::DESCRIPCION);//5
      	$c->addSelectColumn(SubseriePeer::DESCRIPCION);//6
      	$c->addSelectColumn(UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);//7
      	$c->addSelectColumn(UnidadDocumentalPeer::FOLIOS);//8
      	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENCENTRAL);//9
      	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENGESTION);//10
      	$c->addSelectColumn(UnidadDocumentalPeer::UBICACIONENHISTORICO);//11
      	$c->addSelectColumn(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID);//12
    	$c->addSelectColumn(SoporteUnidadDocumentalPeer::DESCRIPCION);//13    	
    	$c->addSelectColumn(UnidadDocumentalPeer::CONTENIDO);//14
        $c->addSelectColumn(UnidadDocumentalPeer::NOTAS);//15
		$c->addSelectColumn(UnidadDocumentalPeer::NUMERO_CAJA);//16
		$c->addSelectColumn(UnidadDocumentalPeer::NUMERO_CARPETA);//17
		$c->addSelectColumn(UnidadDocumentalPeer::GEO_BODEGA);//18
		$c->addSelectColumn(UnidadDocumentalPeer::GEO_CUERPO);//19
		$c->addSelectColumn(UnidadDocumentalPeer::GEO_TORRE);//20
		$c->addSelectColumn(UnidadDocumentalPeer::GEO_PISO);//21
		//*****************************************************************************************************************
		$sql_custom = "(SELECT TOP 1 CONCAT(UNDCREADOR.NOMBRE, ' ', UNDCREADOR.APELLIDO)";
		$sql_custom .= " FROM USUARIO UNDCREADOR";
		$sql_custom .= " JOIN ".UnidaddocumentalUsuarioPeer::TABLE_NAME." USEREXP ON UNDCREADOR.USUARIO_ID = USEREXP.USUARIO_ID";
		$sql_custom .= " WHERE USEREXP.ROLUSUUNIDADDOC_ID = 1";
		$sql_custom .= " AND USEREXP.UNIDADDOCUMENTAL_ID = " . UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID . ")";
		$c->addAsColumn("NOMBRE_CREADOR", $sql_custom); //22		
		//*****************************************************************************************************************
    	$this->resultset = UnidadDocumentalPeer::doSelectStmt($c);
    	$this->filtros_consulta = $parametros_consulta;
    }
	
	public function executeExportarDocs()
	{
		$this->setLayout(false);
		//******************************************************************************************************************//
		$c = new Criteria();
		$c = $this->getBasicCriteria();
		$localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
		$parametros_consulta = "";
		//******************************************************************************************************************//
		$this->username = $this->getUser()->getAttribute('username', '', 'subscriber');
		$c->clearSelectColumns();  	
		$c->addJoin(UnidadDocumentalPeer::SUBSERIE_ID,SubseriePeer::SUBSERIE_ID);
