  public function executeDelete()
  {
    $unidad_documental = UnidadDocumentalPeer::retrieveByPk($this->getRequestParameter('unidaddocumental_id'));
    $this->forward404Unless($unidad_documental);
	$unidad_documental->setEstadounidaddocumentalId(3);
    $unidad_documental->save();

    return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getUnidaddocumentalId().'&localizacion='.$unidad_documental->getLocalizacionunidaddocumentalId());
  }
  
  public function executeDeleteMarcados()
  {
  	/*********************************************************************************************/
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$localizacion = $this->getRequestParameter('localizacionunidaddocumental_id');
  	/*********************************************************************************************/
  	if(trim($localizacion))
  	{
  	    /*********************************************************************************************/
	    if(!$localizacion)
	    	$localizacion = $this->getRequestParameter('localizacion');
	    $currentForm="delete_marcados";
	    $this->verificaPrilegio($currentForm,$localizacion);
	    /*********************************************************************************************/
	  	$c = new Criteria();
	  	$c->add(UnidadDocumentalPeer::MARCA,$usuariologuiado);
	  	$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID,$localizacion);
	  	$all_expedientes = UnidadDocumentalPeer::doSelect($c);
	  	foreach ($all_expedientes as $expedientes ) {
	  		$this->deleteSqlExecute($expedientes->getPrimaryKey());
	  	}
	  	/*********************************************************************************************/
  	}
  	/*********************************************************************************************/
  }
  
