  		$sql = sprintf($query, UnidadDocumentalPeer::TABLE_NAME, UnidadDocumentalPeer::MARCA_ELIMINACION,UnidadDocumentalPeer::MARCA);
        $sentencia = $conexion->prepare($sql);
        $sentencia->execute();  		
  		/*********************************************************************************************/
