        $sentencia = $conexion->prepare($sql);
        $sentencia->execute();
  	}
  }
  
  public function executeDeleting()
  {
	$unidaddocumental_id = trim($this->getRequestParameter('unidaddocumental_id'));
	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	$unidad_documental = UnidadDocumentalPeer::retrieveByPk($unidaddocumental_id);
	$localizacionunidaddocumental_id = $unidad_documental->getLocalizacionunidaddocumentalId();
	$usuario = UsuarioPeer::retrieveByPK($usuariologuiado);
	//****************************************************************************************
	if(empty($unidad_documental) & empty($unidaddocumental_id)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado_cerrar.html');
	}
	//****************************************************************************************
	$unidad_documental_anterior = clone $unidad_documental;
	//****************************************************************************************
	$obs_eliminacion = "Expediente eliminando con proceso de borrado seguro, usuario => %s, fecha eliminación => %s";
	$obs_eliminacion = sprintf($obs_eliminacion,$usuario->getNombreApellido(),date("Y-m-d G:i:s"));
	$current_obs = empty(trim($unidad_documental->getObsEliminacion())) ? $obs_eliminacion : trim($unidad_documental->getObsEliminacion()).','.$obs_eliminacion;
	//****************************************************************************************
	$unidad_documental->setObsEliminacion($current_obs);
	//****************************************************************************************
	try{
		$modulo = "";
		if($localizacionunidaddocumental_id == 1){
			$modulo = "GESTION";
		}else if($localizacionunidaddocumental_id == 2){
			$modulo = "CENTRAL";
		}else if($localizacionunidaddocumental_id == 3){
			$modulo = "HISTORICO";
		}
		//************************************************************************************
		$currentFormDelete = "ARCHIVO_".$modulo."_ELIMINAR_CODIGO";
		if(!$this->tienePrilegio($currentFormDelete)){
			$this->redirect(sfConfig::get('base_simad').'/no_autorizado_cerrar.html');
		}
		//************************************************************************************
		$conexion = Propel::getConnection();
		//************************************************************************************
		//ELIMINAR USUARIOS DE LA UNIDAD DOCUMENTAL
		$set1 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set1 = sprintf($set1, UnidaddocumentalUsuarioPeer::TABLE_NAME, UnidaddocumentalUsuarioPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set1);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LOS CONTENIDOS_UNIDAD_DOCUMENTAL
		$set2 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set2 = sprintf($set2, ContenidoUnidadDocumentalPeer::TABLE_NAME, ContenidoUnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set2);
		$sentencia->execute();            
		//************************************************************************************
		//ELIMINAR LOS PERMISOS PARA LA UNIDAD DOCUMENTAL
		$set5 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set5 = sprintf($set5, PermisoUsuarioUniddocPeer::TABLE_NAME, PermisoUsuarioUniddocPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set5);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LOS CODIGOS ISAD PARA LA UNIDAD DOCUMENTAL
		$set6 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set6 = sprintf($set6, IsadPeer::TABLE_NAME, IsadPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set6);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR DETALLES DE PRESTAMO
		$set1 = "DELETE %s WHERE %s in (SELECT %s FROM %s JOIN %s ON %s = %s WHERE %s = ".$unidaddocumental_id.")";
		$set1 = sprintf($set1, DetallePrestamoPeer::TABLE_NAME, DetallePrestamoPeer::PRESTAMO_ID,DetallePrestamoPeer::PRESTAMO_ID,
					DetallePrestamoPeer::TABLE_NAME,SolicitudPrestamoPeer::TABLE_NAME, DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,
					SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set1);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR PRESTAMOS
		$set1 = "DELETE %s WHERE %s in (SELECT %s FROM %s JOIN %s ON %s = %s WHERE %s = ".$unidaddocumental_id.")";
		$set1 = sprintf($set1, PrestamoPeer::TABLE_NAME, PrestamoPeer::PRESTAMO_ID,DetallePrestamoPeer::PRESTAMO_ID,
					DetallePrestamoPeer::TABLE_NAME,SolicitudPrestamoPeer::TABLE_NAME, DetallePrestamoPeer::SOLICITUDPRESTAMO_ID,
					SolicitudPrestamoPeer::SOLICITUDPRESTAMO_ID,SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set1);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR SOLICITUDES DE PRESTAMO
		$set1 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set1 = sprintf($set1, SolicitudPrestamoPeer::TABLE_NAME, SolicitudPrestamoPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set1);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LOS USUARIO TRANSFERENCIAS PARA LA UNIDAD DOCUMENTAL
		$set7 = "DELETE %s WHERE %s in (SELECT %s FROM %s WHERE %s=".$unidaddocumental_id.")";
		$set7 = sprintf($set7, UsuarioTransferenciaPeer::TABLE_NAME, UsuarioTransferenciaPeer::TRANSFERENCIA_ID,TransferenciaPeer::TRANSFERENCIA_ID,TransferenciaPeer::TABLE_NAME,TransferenciaPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set7);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LAS TRANSFERENCIAS PARA LA UNIDAD DOCUMENTAL
		$set8 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set8 = sprintf($set8, TransferenciaPeer::TABLE_NAME, TransferenciaPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set8);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LOS METADATOS
		$set9 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set9 = sprintf($set9, MetadatosExpedientePeer::TABLE_NAME, MetadatosExpedientePeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set9);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR INTERESADOS DE LA UNIDAD DOCUMENTAL
		$set10 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set10 = sprintf($set10, UnidaddocumentalInteresadosPeer::TABLE_NAME, UnidaddocumentalInteresadosPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set10);
		$sentencia->execute();
		//************************************************************************************
		//ELIMINAR LA UNIDAD DOCUMENTAL
		$set11 = "DELETE %s WHERE %s=".$unidaddocumental_id;			       
		$set11 = sprintf($set11, UnidadDocumentalPeer::TABLE_NAME, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID);
		$sentencia = $conexion->prepare($set11);
		$sentencia->execute();
		//************************************************************************************
		AuditLogPeer::guardarAuditoriaLite(UnidadDocumentalPeer::getOMClass(), $unidad_documental_anterior, $unidad_documental, ModulesEnable::Archivo,
			$unidad_documental->getCodigoBarras(),$usuariologuiado,"delete");
	}
	catch (PropelException $ex)
	{
		$msg_error = 'Error al eliminar el expediente, comuníquese con el administrador. (Error Code '.$ex->getCode().')';
		$this->getUser()->setFlash('error_data', $msg_error);
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getUnidaddocumentalId().'&localizacion='.$unidad_documental->getLocalizacionunidaddocumentalId());
	}
	catch (\Exception $ex)
	{
		$msg_error = 'Ocurrio un error inesperado en la aplicación, intenta de nuevo o comuníquese con el administrador. (Error Code '.$ex->getCode().')';
		$this->getUser()->setFlash('error_data', $msg_error);
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getUnidaddocumentalId().'&localizacion='.$unidad_documental->getLocalizacionunidaddocumentalId());
	}
	catch (\Throwable $ex)
	{
		$msg_error = 'Error interno del servidor, intenta de nuevo o comuníquese con el administrador. (Error Code '.$ex->getCode().')';
		$this->getUser()->setFlash('error_data', $msg_error);
		return $this->redirect($this->getRequest()->getScriptName().'/unidad_documental/show?unidaddocumental_id='.$unidad_documental->getUnidaddocumentalId().'&localizacion='.$unidad_documental->getLocalizacionunidaddocumentalId());
	}
  }
  
  public function getNewCodigoBarras()
  {
	$parametro = ParametroPeer::retrieveByPk(50);
	$new_codigo = $parametro->getValorNumerico() + 1;
	//******************************************************************
	$parametro->setValorNumerico($new_codigo);
	$parametro->save();
	//******************************************************************
	return $new_codigo;
  }

  public function getBasicCriteria()
  {
  	$c = new Criteria();
  	$c->setDistinct();
  	$localizacion = !empty($this->getRequestParameter('localizacionunidaddocumental_id')) ? trim($this->getRequestParameter('localizacionunidaddocumental_id')) : null;
  	$expedientes_antiguos = "";
  	$this->paramsBusqueda = "";
	$isEnableFuid = false;
  	//**********************************************************************************************
  	if(!$localizacion){ $localizacion = trim($this->getRequestParameter('localizacion')); }
  	$parametros_consulta = "";
  	//**********************************************************************************************
  	$usuario_conectado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
  	$regional_conectado = $this->getUser()->getAttribute('regional_id', '', 'subscriber');
  	$entidad_conectado = $this->getUser()->getAttribute('entidad_id', '', 'subscriber');
  	//**********************************************************************************************
  	// CONSULTA POR LOCALIZACION
  	if($localizacion != ""){
  		$c->add(UnidadDocumentalPeer::LOCALIZACIONUNIDADDOCUMENTAL_ID, $localizacion);
  		$parametros_consulta .= "&localizacionunidaddocumental_id=".$localizacion;
  	}
  	//**********************************************************************************************
  	// CONSULTA POR REGIONAL
  	$currentFormListAllRegional = "LISTAR_EXPEDIENTES_TODAS_REGIONALES";
