  		$c->add(UnidadDocumentalPeer::REGIONAL_ID, $regional_conectado);
  	}else if(trim($this->getRequestParameter('regional_id'))){
  		$c->add(UnidadDocumentalPeer::REGIONAL_ID, trim($this->getRequestParameter('regional_id')));
  		$parametros_consulta .= "&regional_id=".trim($this->getRequestParameter('regional_id'));
  	}
  	//**********************************************************************************************
